  ui_story_5001_50010101_28_dialog_content = "Itu benar... Aku yakin Soroz juga tidak akan senang melihatnya.",
  ui_story_5001_50010101_29_dialog_content = "Tidak.",
  ui_story_5001_50010101_30_dialog_content = "Juga, klien bahkan tidak mencantumkan nama mereka! Bagaimana kita harus mengumpulkan pembayaran kita?",
  ui_story_5001_50010101_31_dialog_content = "Yah, itu diposting di papan buletin Persekutuan... Mungkin mereka akan membayar jika terjadi kesalahan?",
