  ui_story_5001_50010101_35_dialog_content = "Tabungan kami habis untuk semua masalah yang kami alami akhir-akhir ini, jadi jika kami melewatkan kesempatan seperti ini...",
  ui_story_5001_50010101_36_dialog_content = "Eh... Apa semuanya benar-benar menjadi seburuk ini? aku bahkan belum menyadarinya...",
  ui_story_5001_50010101_37_dialog_content = "Maksud Anda, Anda tidak melacak berapa banyak uang yang Anda miliki?",
  ui_story_5001_50010101_38_dialog_content = "Omong-omong, laporan tentang \"aktivitas supranatural\" biasanya hanya tipuan atau lelucon, jadi pekerjaan ini seharusnya mudah!",
  ui_story_5001_50010101_39_dialog_content = "Tugas sederhana ini praktis adalah uang gratis, dan itu milik kita untuk diambil!",
  ui_story_5001_50010101_40_dialog_content = "Apakah kamu tidak mendengar? Gratis! Tunggu, kamu tidak berpikir untuk menolaknya, kan?",
  ui_story_5001_50010101_41_dialog_content = "Apakah Anda tahu betapa sulitnya bagi saya untuk mendapatkan pekerjaan ini?",
  ui_story_5001_50010101_42_dialog_content = "Ada segerombolan orang yang berjuang untuk itu di papan! Saya nyaris tidak berhasil keluar di atasnya!",
  ui_story_5001_50010101_43_dialog_content = "...",
  ui_story_5001_50010101_44_dialog_content = "Ini pekerjaan yang mendesak, jadi ayo bergerak!",
  ui_story_5001_50010101_45_dialog_content = "Baiklah, kurasa tidak ada salahnya jika kita pergi untuk melihat...",
  ui_story_5001_50010201_1_dialog_content = "<color=#e8d9bb>Gurun Rediesel, di atas Tail Street</color>",
  ui_story_5001_50010201_2_dialog_content = "PlayerName, kami telah tiba di sekitar <color=#FFB400>Jalan Ekor</color>.",
  ui_story_5001_50010201_3_dialog_content = "Area tersebut kemungkinan milik Rediesel Wrench. Aku tidak akan terbang lebih dekat.",
  ui_story_5001_50010201_4_dialog_content = "Tidak apa-apa Soroz, kita akan mendarat di luar Tail Street.",
  ui_story_5001_50010201_A1_dialog_content = "Saya tidak menyalahkan Anda karena merasa tidak nyaman, setelah apa yang dilakukan oleh Rediesel Wrench terakhir kali.",
  ui_story_5001_50010201_5_dialog_content = "Tempat ini jauh lebih kecil dari yang saya bayangkan. Yuk, segera ke inti dari \"aktivitas supranatural\" ini!",
  ui_story_5001_50010201_6_dialog_content = "Saya berharap Anda beruntung dalam misi Anda.",
  ui_story_5001_50010201_8_dialog_content = "Ini agak mengerikan... Di mana semua orang? Kupikir kita harus menyelinap ke tempat ini, tapi...",
  ui_story_5001_50010201_9_dialog_content = "Anda benar, saya rasa tidak ada orang yang tinggal di sini sama sekali. Itu benar-benar kosong ...",
  ui_story_5001_50010201_10_dialog_content = "Apakah ini benar-benar bagian dari wilayah Rediesel Wrench? Sulit dipercaya, karena sangat sepi.",
  ui_story_5001_50010201_11_dialog_content = "Ada kemungkinan \"aktivitas supranatural\" ini benar-benar terjadi, Wakil...",
  ui_story_5001_50010201_12_dialog_content = "Hmm…",
  ui_story_5001_50010201_13_dialog_content = "Tidakkah menurutmu ada yang aneh dengan ini?",
  ui_story_5001_50010201_14_dialog_content = "Apa maksudmu?",
  ui_story_5001_50010201_15_dialog_content = "Bukankah hantu biasanya terjadi di tempat-tempat terlantar seperti ini?",
  ui_story_5001_50010201_16_dialog_content = "Satu-satunya hal yang menurut saya aneh adalah hadiah yang mereka tawarkan untuk pekerjaan ini. Saya benar-benar berpikir Anda telah ditipu, Vice.",
  ui_story_5001_50010201_17_dialog_content = "Eh, bukan itu! Perhatikan baik-baik!",
  ui_story_5001_50010201_18_dialog_content = "Semua pintu dan jendela di sini tertutup rapat, dan kondisinya sangat baik. Jika kita melihat ke detail ...",
  ui_story_5001_50010201_19_dialog_content = "Jika Anda menyeka tangan Anda di sini, atau salah satu dari tempat-tempat ini...",
  ui_story_5001_50010201_20_dialog_content = "Tidak ada debu.",
  ui_story_5001_50010201_21_dialog_content = "Tapi tidak ada seorang pun yang terlihat. Apakah Anda mengatakan tempat ini tidak ditinggalkan?",
  ui_story_5001_50010201_22_dialog_content = "Jika suatu tempat telah ditinggalkan untuk waktu yang lama, setidaknya akan ada lapisan kotoran atau debu pada sesuatu, kan? Tapi semua bangunan ini relatif bersih.",
  ui_story_5001_50010201_23_dialog_content = "Anda benar... Seolah-olah seseorang telah memelihara Tail Street secara berkala.",
  ui_story_5001_50010201_24_dialog_content = "Seharusnya ada banyak jendela yang pecah dan pintu yang hilang juga, bukan begitu?",
  ui_story_5001_50010201_25_dialog_content = "Pernahkah Anda berada dalam situasi seperti ini sebelumnya?",
  ui_story_5001_50010201_26_dialog_content = "Tidak, tapi bukankah kebanyakan cerita hantu dimulai seperti ini?",
  ui_story_5001_50010201_27_dialog_content = "Kau benar.",
  ui_story_5001_50010201_28_dialog_content = "Haruskah kita mencoba mengetuk beberapa pintu?",
  ui_story_5001_50010201_29_dialog_content = "Ya, mari kita berpisah dan mencobanya.",
  ui_story_5001_50010201_31_dialog_content = "Kami kembali ke sini lagi. Lagipula tempat ini sangat kecil.",
  ui_story_5001_50010201_32_dialog_content = "Saya tidak menemukan petunjuk apa pun di pihak saya. Apakah Anda pikir saya tidak mengetuk cukup keras?",
  ui_story_5001_50010201_33_dialog_content = "Tidak mungkin, bahkan aku bisa mendengar ketukanmu. Maksudku, jika benar-benar ada hantu di sini, aku yakin kau menakuti mereka...",
  ui_story_5001_50010201_34_dialog_content = "Bagaimana denganmu? Ada keberuntungan?",
  ui_story_5001_50010201_35_dialog_content = "Tidak.",
  ui_story_5001_50010201_36_dialog_content = "Apakah Anda benar-benar mencoba mencari petunjuk?",
  ui_story_5001_50010201_37_dialog_content = "Hei, aku bahkan menggunakan kemampuan psikisku untuk menjelajahi area itu! Tidak ada apa-apa di sini.",
  ui_story_5001_50010201_39_dialog_content = "Eh, jadi bagaimana kita bisa menyelesaikan tugas aneh ini? Kami belum membuat kemajuan!",
  ui_story_5001_50010201_40_dialog_content = "Tunggu, aku tahu! Kebanyakan hal supernatural terjadi di tengah malam, bukan? Saya yakin kita akan menemukan beberapa jawaban setelah matahari terbenam!",
  ui_story_5001_50010201_41_dialog_content = "Anda tidak menyerah, kan...",
  ui_story_5001_50010201_42_dialog_content = "Baiklah, mari kita kembali ke Soroz dan menunggu di sana. Tempat ini membuatku merinding...",
  ui_story_5001_50010201_43_dialog_content = "Sepakat. Ayo pergi...",
  ui_story_5001_50010201_44_dialog_content = "…!",
  ui_story_5001_50010201_45_dialog_content = "Ada apa?",
  ui_story_5001_50010201_46_dialog_content = "Tunggu sebentar.",
  ui_story_5001_50010201_47_dialog_content = "...",
  ui_story_5001_50010201_48_dialog_content = "Aku juga merasakannya... Di belakang kita?",
  ui_story_5001_50010201_49_dialog_content = "Ya. Tiga dari mereka... Tidak, masih ada lagi. Mereka dekat...",
  ui_story_5001_50010201_50_dialog_content = "Dipahami. Apakah Anda membawa senjata Anda?",
  ui_story_5001_50010201_51_dialog_content = "Hmph, apakah Anda bahkan perlu bertanya?",
  ui_story_5001_50010201_52_dialog_content = "Sepertinya tempat ini akan menjadi jauh lebih hidup...",
  ui_story_5001_50010201_53_dialog_content = "Graaaah...!",
  ui_story_5001_50010201_54_dialog_content = "Mari kita tuliskan \"aktivitas supranatural\" pada Eclipsites ini dan singkirkan mereka.",
  ui_story_5001_50010202_1_dialog_content = "Angin sepoi-sepoi!",
  ui_story_5001_50010202_2_dialog_content = "Kalau dipikir-pikir, mungkin pekerjaan ini tidak serumit yang saya bayangkan.",
  ui_story_5001_50010202_3_dialog_content = "Masuk akal jika \"aktivitas supranatural\" itu tidak lebih dari masalah Eclipsite.",
  ui_story_5001_50010202_4_dialog_content = "Kedengarannya seperti kesimpulan yang masuk akal bagi saya.",
  ui_story_5001_50010202_5_dialog_content = "Anu…",
  ui_story_5001_50010202_6_dialog_content = "Mengapa Anda terlihat sangat kecewa?",
  ui_story_5001_50010202_7_dialog_content = "Mari kita lihat lagi dan pastikan kita mendapatkan semua Eclipsites di sini.",
  ui_story_5001_50010202_8_dialog_content = "Kami akan kembali ke Umbraton setelah kami selesai dan mencari pekerjaan lain. Yang ini tidak layak untuk kita sementara di sini.",
  ui_story_5001_50010202_9_dialog_content = "Hah?",
  ui_story_5001_50010202_10_dialog_content = "Apakah Anda menemukan sesuatu yang lain?",
  ui_story_5001_50010202_11_dialog_content = "Lihat keranjang bambu ini!",
  ui_story_5001_50010202_12_dialog_content = "Hmm? Biarku lihat...",
  ui_story_5001_50010202_13_dialog_content = "Apel, ceri... Dan semangka besar juga.",
  ui_story_5001_50010202_14_dialog_content = "Seseorang mengukir wajah tersenyum ke dalam semangka...",
  ui_story_5001_50010202_15_dialog_content = "Semua buah-buahan ini terlihat sangat segar... Apakah Anda yakin tidak merasakan orang lain di sini, PlayerName?",
  ui_story_5001_50010202_16_dialog_content = "Ya. Entah seseorang meninggalkan keranjang ini di sini sebelum kita tiba, atau...",
  ui_story_5001_50010202_17_dialog_content = "Ada kehadiran di sini yang bahkan aku tidak bisa mendeteksinya.",
  ui_story_5001_50010202_18_dialog_content = "Bagaimana kalau...",
  ui_story_5001_50010202_19_dialog_content = "Arwah?",
  ui_story_5001_50010202_20_dialog_content = "S-Stop... Kau membuatku merinding...",
  ui_story_5001_50010202_21_dialog_content = "Tunggu, kamu dari Illumina! Bagaimana Anda bisa percaya pada hal-hal takhayul seperti itu?",
  ui_story_5001_50010202_22_dialog_content = "Juga, hantu macam apa yang meninggalkan keranjang buah di depan rumah seseorang?",
  ui_story_5001_50010202_23_dialog_content = "Hanya ada satu kesimpulan.",
  ui_story_5001_50010202_24_dialog_content = "Ada orang yang tinggal di rumah-rumah ini.",
  ui_story_5001_50010202_25_dialog_content = "Adapun mengapa tidak ada seorang pun di sini ... Mungkin mereka semua pergi ke suatu tempat?",
  ui_story_5001_50010202_26_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5001_50010202_27_dialog_content = "Suara apa itu?",
  ui_story_5001_50010202_28_dialog_content = "Apa?",
  ui_story_5001_50010202_30_dialog_content = "Lihat!",
  ui_story_5001_50010202_31_dialog_content = "Apakah keranjang buah... gemetar?",
  ui_story_5001_50010202_32_dialog_content = "Apakah masih ada Eclipsites di dekat sini? aku tidak merasakan apapun...",
  ui_story_5001_50010202_33_dialog_content = "...",
  ui_story_5001_50010202_34_dialog_content = "Ah.",
  ui_story_5001_50010202_35_dialog_content = "Apa...?",
  ui_story_5001_50010202_36_dialog_content = "<size=45><color=#e8d9bb>Memukul!</color></size>",
  ui_story_5001_50010202_37_dialog_content = "<size=45>Aduh!!!</size>",
  ui_story_5001_50010301_1_dialog_content = "...",
  ui_story_5001_50010301_2_dialog_content = "Apakah masih ada di wajah saya?",
  ui_story_5001_50010301_3_dialog_content = "Tidak, sekarang sudah bersih. Bersyukurlah dia tidak melempar semangka.",
  ui_story_5001_50010301_4_dialog_content = "Masih sakit... Aku tidak tahu apakah rotinya keras, atau apakah lengan lemparnya sekuat itu...",
  ui_story_5001_50010301_5_dialog_content = "Um, jadi... Kenapa kau melakukan itu, nona?",
  ui_story_5001_50010301_6_dialog_content = "...",
  ui_story_5001_50010301_7_dialog_content = "Kenapa dia tidak bicara?",
  ui_story_5001_50010301_8_dialog_content = "Halo, nama saya Vice.",
