  ui_story_5001_50010301_10_dialog_content = "...",
  ui_story_5001_50010301_11_dialog_content = "Kurasa dia tidak mengerti kita, Vice.",
  ui_story_5001_50010301_12_dialog_content = "Kenapa aku tidak bisa merasakan kehadirannya? Aku tidak tidur nyenyak semalam... Mungkinkah itu mempengaruhi kekuatanku?",
  ui_story_5001_50010301_13_dialog_content = "(Apa itu tadi?)",
  ui_story_5001_50010301_14_dialog_content = "PlayerName? Apakah Anda melakukan zonasi lagi?",
  ui_story_5001_50010301_15_dialog_content = "Sebuah gambar... terlintas begitu saja di pikiranku.",
  ui_story_5001_50010301_16_dialog_content = "Apa itu?",
  ui_story_5001_50010301_17_dialog_content = "Sebuah raksasa <color=#FFB400>wadah</color>, di tempat yang sangat dingin... Dan dia ada di dalamnya.",
  ui_story_5001_50010301_18_dialog_content = "Sebuah wadah? Jenis apa?",
  ui_story_5001_50010301_19_dialog_content = "Aku tidak tahu.",
  ui_story_5001_50010301_20_dialog_content = "Mungkin Anda entah bagaimana bisa melihat masa lalunya? Jika itu masalahnya, tidakkah menurut Anda dia membutuhkan bantuan?",
  ui_story_5001_50010301_21_dialog_content = "Eclipsites dapat muncul kapan saja di sini. Mengapa kita tidak membawanya bersama kita?",
  ui_story_5001_50010301_22_dialog_content = "Kami akan memeriksanya kembali di Illumina. Bagaimanapun, kita tidak bisa meninggalkannya begitu saja di sini.",
  ui_story_5001_50010301_23_dialog_content = "Tentu saja kita harus membantu, tapi...",
  ui_story_5001_50010301_24_dialog_content = "Sesuatu memberitahuku dia tidak ingin ikut dengan kita.",
  ui_story_5001_50010301_25_dialog_content = "Pikirkanlah: reaksi pertamanya adalah memukul wajahku dengan sepotong roti... Mungkin dia mengira kita adalah musuhnya, dan dia mencoba membawa kita ke luar kota?",
  ui_story_5001_50010301_26_dialog_content = "Aduh… yah…",
