orang jahat?]],
  ui_story_5001_50010301_31_dialog_content = "…!!",
  ui_story_5001_50010301_32_dialog_content = "Selesaikan, PlayerName! Anda membuatnya takut!",
  ui_story_5001_50010301_33_dialog_content = "Dia sepertinya tidak mempercayaimu sama sekali, PlayerName.",
  ui_story_5001_50010301_34_dialog_content = "Aku menyerah... Kenapa kau tidak mencobanya? Dia sepertinya lebih mempercayaimu.",
  ui_story_5001_50010301_35_dialog_content = "Halo! Apakah Anda memerlukan bantuan?",
  ui_story_5001_50010301_36_dialog_content = "...",
  ui_story_5001_50010301_37_dialog_content = "Apakah kamu terluka? Apa anda merasa mual? Kami dapat membantu Anda, jika Anda mau.",
  ui_story_5001_50010301_38_dialog_content = "...",
  ui_story_5001_50010301_39_dialog_content = "Bisakah kamu mengerti saya? Apakah Anda perlu saya untuk ... berbicara lebih lambat?",
  ui_story_5001_50010301_40_dialog_content = "...",
  ui_story_5001_50010301_41_dialog_content = "Saya ambil kembali. Saya tidak berpikir dia mempercayai siapa pun.",
  ui_story_5001_50010301_42_dialog_content = "Anu…",
  ui_story_5001_50010301_43_dialog_content = "Apa?",
  ui_story_5001_50010301_44_dialog_content = "Mmm…",
  ui_story_5001_50010301_45_dialog_content = "Heee!",
  ui_story_5001_50010301_46_dialog_content = "PlayerName, I... Saya pikir dia mencoba untuk berbicara! Lihat, dia bahkan mengangkat tangannya! Dia mengerti saya, bukan begitu?",
  ui_story_5001_50010301_47_dialog_content = "Ya saya berpikir begitu!",
  ui_story_5001_50010301_48_dialog_content = "Dia jelas lebih mempercayai Vice daripada kamu, PlayerName.",
  ui_story_5001_50010301_49_dialog_content = "Ini bukan waktu atau tempat, Soroz... Datang saja jemput kami, ya?",
  ui_story_5001_50010301_50_dialog_content = "Tolong hilangkan Eclipsites yang tersisa sebelum aku mendarat. Tampaknya ada beberapa dari mereka yang mendekati Tail Street.",
  ui_story_5001_50010301_51_dialog_content = "Baiklah baiklah...",
  ui_story_5001_50010302_1_dialog_content = "Ayo, kita harus pergi!",
  ui_story_5001_50010302_2_dialog_content = "...",
  ui_story_5001_50010302_3_dialog_content = "Ada apa?",
  ui_story_5001_50010302_4_dialog_content = "Dia sepertinya melihat sesuatu, Vice.",
  ui_story_5001_50010302_5_dialog_content = "Tapi tidak ada apa-apa di sana...",
  ui_story_5001_50010302_6_dialog_content = "Kau merasakan sesuatu, PlayerName?",
  ui_story_5001_50010302_7_dialog_content = "Tidak sama sekali, tapi aku tidak yakin lagi, karena aku tidak bisa merasakannya. Mungkin...",
  ui_story_5001_50010302_8_dialog_content = "Mungkin ada yang spesial dari dia? Apakah Anda pikir itu ada hubungannya dengan visi masa lalunya yang Anda lihat?",
  ui_story_5001_50010302_9_dialog_content = "Apakah ada orang lain di sini? Bisakah kamu ceritakan pada saya?",
  ui_story_5001_50010302_10_dialog_content = "...",
  ui_story_5001_50010302_11_dialog_content = "Jika ada orang lain di sini, kita...",
  ui_story_5001_50010302_12_dialog_content = "Saya telah tiba. Kita harus pergi sebelum Eclipsites mencapai kita.",
  ui_story_5001_50010302_13_dialog_content = "!!!",
  ui_story_5001_50010302_14_dialog_content = "Heeeeeeee!",
  ui_story_5001_50010302_15_dialog_content = "Hmm…",
  ui_story_5001_50010302_A1_dialog_content = "Dia melompat tepat ke Colossus! Dia cukup berani, setelah semua ...",
  ui_story_5001_50010302_16_dialog_content = "Mari kita pastikan dia aman. Kami akan kembali dan membahas ini di lain waktu.",
  ui_story_5001_50010401_1_dialog_content = "Mari kita mulai dengan beberapa perkenalan.",
  ui_story_5001_50010401_2_dialog_content = "Nama saya PlayerName. Siapa namamu?",
  ui_story_5001_50010401_3_dialog_content = "...",
  ui_story_5001_50010401_4_dialog_content = "Pff.",
  ui_story_5001_50010401_5_dialog_content = "Apa yang kamu tertawakan?",
  ui_story_5001_50010401_6_dialog_content = "Tidak ada, saya hanya mengingat sesuatu yang lucu. Maaf tentang itu.",
  ui_story_5001_50010401_7_dialog_content = "Saya mencoba yang terbaik untuk membuka jalur komunikasi di sini, apakah Anda keberatan?",
  ui_story_5001_50010401_8_dialog_content = "Baiklah, tapi tidakkah menurutmu kau hanya akan menakutinya lagi dengan ekspresi wajahmu itu?",
  ui_story_5001_50010401_9_dialog_content = "Benarkah?",
  ui_story_5001_50010401_10_dialog_content = "Betul sekali. Jika Anda menganggap ini lebih serius, dia bahkan mungkin menangis.",
  ui_story_5001_50010401_11_dialog_content = "Lalu haruskah saya mencoba terlihat sedikit lebih baik? Mungkin lebih energik?",
  ui_story_5001_50010401_12_dialog_content = "...",
  ui_story_5001_50010401_13_dialog_content = "Dia melihat-lihat Soroz, PlayerName! Sekarang adalah kesempatan Anda!",
  ui_story_5001_50010401_14_dialog_content = "Ah, a-kita sekarang di Soroz. Cukup keren, ya?",
  ui_story_5001_50010401_15_dialog_content = "Soroz dapat membawa Anda ke mana pun Anda ingin pergi di dunia!",
  ui_story_5001_50010401_16_dialog_content = "Dan Soroz bahkan memiliki banyak kamar di dalamnya. Mau pergi melihat?",
  ui_story_5001_50010401_17_dialog_content = "!!",
  ui_story_5001_50010401_18_dialog_content = "H-Hei! Pelan-pelan sedikit!",
  ui_story_5001_50010401_19_dialog_content = "Dia tampaknya cukup tertarik pada Colossi, ya? Dia terlihat jauh lebih gugup sekarang.",
  ui_story_5001_50010401_20_dialog_content = "Mungkin dia tidak tertarik dengan PlayerName?",
  ui_story_5001_50010401_21_dialog_content = "Hentikan, kalian berdua! Bisakah Anda bergegas dan mengunci area berbahaya?",
  ui_story_5001_50010401_22_dialog_content = "Sudah kembali? Apakah Anda bersenang-senang?",
  ui_story_5001_50010401_23_dialog_content = "T... Terima... Astaga...",
  ui_story_5001_50010401_24_dialog_content = "Dia terlihat kecil dan rapuh, tapi... dia praktis terbang seperti hantu...",
  ui_story_5001_50010401_25_dialog_content = "Tidak, saya pikir Anda harus lebih banyak berolahraga.",
  ui_story_5001_50010401_27_dialog_content = "Aku hanya berharap dia bisa terus melihat ke luar jendela seperti ini lebih lama lagi...",
  ui_story_5001_50010401_28_dialog_content = "Dia bisa melihat semuanya dari sana... Siapa yang tidak akan menikmati pemandangan itu?",
  ui_story_5001_50010401_29_dialog_content = "Saya tidak pernah berpikir dia akan begitu ingin tahu tentang dunia luar ... Kemudian lagi, dia sangat bersemangat ketika dia melompat.",
  ui_story_5001_50010401_30_dialog_content = "Mungkin dia hanya suka memiliki tempat yang besar untuk bermain? Dia seperti anak kecil...",
  ui_story_5001_50010401_31_dialog_content = "Bagaimanapun, membantunya rileks adalah hal yang baik.",
  ui_story_5001_50010401_32_dialog_content = "Aku akan memberinya pemeriksaan cepat sekarang setelah dia tenang.",
  ui_story_5001_50010401_34_dialog_content = "Sehat? Apakah itu enak?",
  ui_story_5001_50010401_35_dialog_content = "S-Pelan-pelan, kamu mungkin tersedak! Kami memiliki lebih banyak minuman, jika Anda suka.",
  ui_story_5001_50010401_37_dialog_content = "Apakah Anda ingin sesuatu untuk dimakan juga?",
  ui_story_5001_50010401_38_dialog_content = "...",
  ui_story_5001_50010401_39_dialog_content = "Apakah Anda merasa terluka di mana saja?",
  ui_story_5001_50010401_40_dialog_content = "...",
  ui_story_5001_50010401_41_dialog_content = "Saya akan membiarkan Anda menikmati pemandangan, kalau begitu. Beri tahu saya jika Anda merasa tidak enak badan.",
  ui_story_5001_50010401_42_dialog_content = "Oke…",
  ui_story_5001_50010401_43_dialog_content = "Dia terlihat cukup sehat, bukan begitu?",
  ui_story_5001_50010401_44_dialog_content = "Memang benar, dia tidak terlihat sakit atau terluka sama sekali... Tapi ada yang tidak beres...",
  ui_story_5001_50010401_45_dialog_content = "Untuk satu hal, denyut nadinya benar-benar aneh.",
  ui_story_5001_50010401_46_dialog_content = "Semuanya menunjuk pada kondisi yang tidak normal, tetapi saya tidak tahu apa atau di mana masalahnya ...",
  ui_story_5001_50010401_47_dialog_content = "Kita harus cepat kembali ke Illumina dan memeriksakannya secara menyeluruh!",
  ui_story_5001_50010401_48_dialog_content = "Tapi bagaimana dengan pekerjaan? Bisakah kita pulang dengan tangan kosong?",
  ui_story_5001_50010401_49_dialog_content = "Anda benar-benar memiliki prioritas yang lurus, bukan?",
  ui_story_5001_50010401_50_dialog_content = "Namun, saya masih memiliki pertanyaan tentang apa yang dia lakukan di Tail Street.",
  ui_story_5001_50010401_51_dialog_content = "Jika itu benar-benar bagian dari wilayah Rediesel Wrench, mereka harus tahu sesuatu tentang semua ini.",
  ui_story_5001_50010401_52_dialog_content = "Dapatkah Anda mengingat detail lain dari penglihatan yang Anda lihat sebelumnya?",
  ui_story_5001_50010401_53_dialog_content = "Coba kuingat...",
  ui_story_5001_50010401_54_dialog_content = "Tubuhnya terhubung ke banyak tabung... Dan ada berbagai macam perangkat di sekelilingnya.",
  ui_story_5001_50010401_55_dialog_content = "Ketika Anda mengatakannya seperti itu, sepertinya dia berada di dalam semacam fasilitas.",
  ui_story_5001_50010401_56_dialog_content = "Mungkin... Tapi fasilitas seperti apa?",
  ui_story_5001_50010401_57_dialog_content = "Apakah itu laboratorium pribadi seseorang?",
  ui_story_5001_50010401_58_dialog_content = "Itu mungkin... Hei, menurutmu tidak...",
  ui_story_5001_50010401_59_dialog_content = "Kunci Rediesel?",
  ui_story_5001_50010401_60_dialog_content = "Tidak mungkin... Perlengkapan semacam itu bukan gaya mereka.",
  ui_story_5001_50010401_61_dialog_content = "Itu benar, saya hanya pernah mendengar mereka tertarik untuk memodifikasi mesin, bukan orangnya...",
  ui_story_5001_50010401_62_dialog_content = "Selain itu, Sinsa dengan jas lab...",
  ui_story_5001_50010401_63_dialog_content = "Aku bahkan tidak bisa membayangkan seperti apa bentuknya!",
  ui_story_5001_50010401_64_dialog_content = "A-Apapun masalahnya, jika fasilitas itu ada dan tubuhnya benar-benar telah dimodifikasi...",
  ui_story_5001_50010401_A1_dialog_content = "Seseorang, atau beberapa kelompok, perlu menjawabnya. Kami harus terus menyelidiki masalah ini.",
  ui_story_5001_50010401_65_dialog_content = "Sepakat. Setelah kita kembali, saya akan melihat ke arsip Illumina untuk petunjuk lebih lanjut.",
  ui_story_5001_50010501_A1_dialog_content = "Ada apa, PlayerName? Komunikator Anda berdering tanpa henti...",
  ui_story_5001_50010501_A2_dialog_content = "Itu dari <color=#FFB400>Kunci Pas Rediesel</color>.",
  ui_story_5001_50010501_1_dialog_content = "Kunci Rediesel?",
  ui_story_5001_50010501_2_dialog_content = "Betul sekali. Mereka telah mengirim permintaan komunikasi dari suatu tempat terdekat!",
  ui_story_5001_50010501_4_dialog_content = "Jangan bilang mereka tahu tentang kita pergi ke Tail Street?",
  ui_story_5001_50010501_5_dialog_content = "Tapi kami tidak melakukan apa-apa! Apa menurutmu... itu karena kita menyelamatkan gadis itu?",
  ui_story_5001_50010501_6_dialog_content = "*Melihat gadis yang sedang tidur*",
  ui_story_5001_50010501_7_dialog_content = "Bagaimanapun, kita harus mendengar apa yang mereka katakan!",
  ui_story_5001_50010501_8_dialog_content = "Ha, maaf karena tidak membuat pintu masuk yang megah, PlayerName! Masih ingat aku?",
  ui_story_5001_50010501_9_dialog_content = "Yo, kekasih dari Illumina itu juga ada di sini!",
  ui_story_5001_50010501_10_dialog_content = "Maaf mengganggu, kami hanya lewat.",
  ui_story_5001_50010501_11_dialog_content = "Tidak peduli siapa Anda, ini adalah wilayah KAMI, sekarang turunkan pantat Anda ke tanah, PRONTO!",
  ui_story_5001_50010501_12_dialog_content = "Colossus ini dan semua orang di dalamnya adalah milik KITA sekarang!",
  ui_story_5001_50010501_13_dialog_content = "Sama seperti sebelumnya, saya mengerti.",
  ui_story_5001_50010501_14_dialog_content = "Ugh, aku tidak bisa menunggu lebih lama lagi, Regina! Mari kita meledakkan mereka!",
  ui_story_5001_50010501_15_dialog_content = "Jangan menyela ketika saya sedang berbicara! Ehem, dengarkan! Bos kami akan datang untuk inspeksi! Anda brengsek mengambil sesuatu yang bukan milik Anda!",
  ui_story_5001_50010501_16_dialog_content = "Hah? Anda mengatakan kami mencuri sesuatu dari Anda, DAN Anda ingin mencari Colossus kami?",
  ui_story_5001_50010501_17_dialog_content = "Kami hanya mencoba untuk menemukan apa yang menjadi milik kami, itu saja.",
  ui_story_5001_50010501_18_dialog_content = "Apa yang kita lakukan sekarang? Haruskah kita berhenti dan membiarkan mereka mencari Soroz?",
  ui_story_5001_50010501_19_option_content = [[
Seperti neraka!
Kita keluar dari sini!]],
  ui_story_5001_50010501_20_dialog_content = "Apa, dan memberi mereka kesempatan untuk membunuh kita semua?",
  ui_story_5001_50010501_21_option_content = [[
Apakah Anda yakin itu bukan apa-apa?
lebih dari pemeriksaan?]],
  ui_story_5001_50010501_22_dialog_content = "Kedengarannya seperti Anda hanya mencoba merampok kami, tapi kali ini kami berada di langit!",
  ui_story_5001_50010501_23_dialog_content = "Anda pikir mesin Anda dapat menahan Anda di udara lebih lama? Hah! Jangan meremehkan Kunci Rediesel!",
  ui_story_5001_50010501_24_dialog_content = "O-Mesin kami benar-benar telah berhenti! Tapi kapan mereka...",
  ui_story_5001_50010501_25_dialog_content = "Memeriksa... Tampaknya ada halangan yang tidak diketahui di dalam mesin. Monster macam apa mereka?",
  ui_story_5001_50010501_26_dialog_content = "Tapi Illumina dan Rediesel Wrench memiliki kesepakatan tentang pertempuran! Dengan ini saya menuntut untuk berbicara dengan pemimpin Anda!",
  ui_story_5001_50010501_27_dialog_content = "Bah, persetujuan Anda tidak lebih dari kertas toilet, sejauh yang kami pedulikan.",
  ui_story_5001_50010501_28_dialog_content = "Saya seharusnya tidak berharap banyak dari orang-orang biadab yang tidak beradab itu!",
  ui_story_5001_50010501_29_dialog_content = "Baiklah, jika itu yang Anda inginkan!",
  ui_story_5001_50010501_30_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5001_50010501_31_dialog_content = "Hei, jangan terlalu kasar, atau kita semua akan hidup untuk menyesalinya!",
  ui_story_5001_50010501_32_dialog_content = "Aku tahu, aku tahu!",
  ui_story_5001_50010501_33_dialog_content = "Hei, mereka dari Illumina! Itu adalah peringatan pertama dan terakhirmu! Menangkap drift saya?",
  ui_story_5001_50010501_34_dialog_content = "Bisakah kamu melepaskannya, Soroz?",
  ui_story_5001_50010501_35_dialog_content = "Akan kucoba.",
  ui_story_5001_50010501_36_dialog_content = "PlayerName! Setiap orang! Kuatkan dirimu!",
  ui_story_5001_50010501_37_dialog_content = "Apakah Anda menemukannya?",
  ui_story_5001_50010501_38_dialog_content = "Kami menemukannya! Dia ada di Colossus!",
  ui_story_5001_50010501_39_dialog_content = "Sepertinya mereka tidak akan berhenti dalam waktu dekat, bos! Apa rencananya?",
  ui_story_5001_50010501_40_dialog_content = "Apakah karena mereka tidak ingin berhenti... atau karena mereka tidak tahu bagaimana cara berhenti?!",
  ui_story_5001_50010501_41_dialog_content = "Saya tidak bisa lagi mempertahankan pola penerbangan saya. Kami dengan cepat kehilangan ketinggian.",
  ui_story_5001_50010501_42_dialog_content = "Kamu harus terus berusaha, Soroz! Kita sudah terlalu dekat dengan tanah...",
  ui_story_5001_50010501_43_dialog_content = "!!!!!",
  ui_story_5001_50010501_44_dialog_content = "Wow! Bicara tentang menarik rem tangan, bos! Ha ha ha ha!",
  ui_story_5001_50010501_45_dialog_content = "Aaaaah!! Apa yang sedang terjadi?!",
  ui_story_5001_50010501_46_dialog_content = "Mereka... Mereka membawa Soroz ke tanah?! Kekuatan macam apa ini?!",
  ui_story_5001_50010501_47_dialog_content = "Sial... Semua kebisingan ini pasti akan menarik lebih dari beberapa sakit kepala.",
  ui_story_5001_50010501_48_dialog_content = "Ayo, kita urus bisnis dan pergi dari sini!",
  ui_story_5001_50010501_49_dialog_content = "<color=#e8d9bb>Terperangkap di dalam pasir gurun yang panas, Soroz telah kehilangan harapan untuk melarikan diri...</color>",
  ui_story_5001_50010501_50_dialog_content = "*Batuk-batuk*",
  ui_story_5001_50010501_51_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_5001_50010501_52_dialog_content = "Aku baik-baik saja.",
  ui_story_5001_50010501_53_dialog_content = "Ayo keluar! Tidak ada gunanya melawan lagi!",
  ui_story_5001_50010501_54_dialog_content = "Tapi pertama-tama, saya sarankan Anda mengurus semua Eclipsites yang Anda gambar — pendaratan Anda membuat suara besar!",
  ui_story_5001_50010501_55_dialog_content = "Anda menyalahkan AS untuk itu?!",
  ui_story_5001_50010601_1_dialog_content = "Kita bertemu lagi, PlayerName.",
  ui_story_5001_50010601_2_option_content = "Apa kita pernah bertemu sebelumnya?",
  ui_story_5001_50010601_3_dialog_content = "\"Apa kita pernah bertemu sebelumnya?\" Mungkin ini akan menyegarkan ingatan Anda!",
  ui_story_5001_50010601_4_dialog_content = "Berkedip Memantul Bing Bang Boom!!",
  ui_story_5001_50010601_5_dialog_content = "Baiklah, baiklah, aku ingat! Singkirkan saja!",
  ui_story_5001_50010601_6_option_content = "Ya... Kita bertemu lagi.",
  ui_story_5001_50010601_7_option_content = "Tidak seperti aku benar-benar ingin...",
  ui_story_5001_50010601_8_dialog_content = "Apa katamu?",
  ui_story_5001_50010601_9_dialog_content = "T-Tidak ada! Um, kamu tidak hanya melakukan ini untuk merampok kami, kan?",
  ui_story_5001_50010601_10_dialog_content = "Biar langsung ke intinya.",
  ui_story_5001_50010601_11_dialog_content = "Saya tahu saya mengatakannya sebelumnya, tetapi lain kali saya melihat Anda, saya mengambil Colossus ini untuk saya sendiri.",
  ui_story_5001_50010601_12_dialog_content = "D-Apakah kamu mengatakan itu sebelumnya?",
  ui_story_5001_50010601_13_dialog_content = "Untuk kali ini, aku rela melepaskanmu lagi. Hanya...",
  ui_story_5001_50010601_14_dialog_content = "<color=#FFB400>Malam</color> tidak akan bersamamu.",
  ui_story_5001_50010601_15_dialog_content = "Eve?",
  ui_story_5001_50010601_16_dialog_content = "Gadis yang kau ambil dari Tail Street.",
  ui_story_5001_50010601_17_dialog_content = "Jadi namanya Hawa?",
  ui_story_5001_50010601_18_dialog_content = "Maaf, tapi bagaimana kami bisa percaya dia akan aman bersamamu tanpa bukti apapun?",
  ui_story_5001_50010601_19_dialog_content = "Bukti? Kalian punya keberanian, menculik seseorang dari rumah mereka dan kemudian menuntut bukti untuk melepaskan mereka! Anda orang jahat di sini, bukan kami!",
  ui_story_5001_50010601_20_dialog_content = "Jangan memutar hal-hal di luar konteks, Sinsa. Kami sedang mengerjakan tugas ketika kami bertemu dengannya di jalan.",
  ui_story_5001_50010601_21_dialog_content = "Dia tampak seperti sedang dalam masalah saat itu, dan tidak ada orang lain di Tail Street yang bisa membantu.",
  ui_story_5001_50010601_22_dialog_content = "Itu bukan urusan Anda.",
  ui_story_5001_50010601_23_dialog_content = "Jadi kita seharusnya meninggalkan seorang gadis malang di jalan, sendirian?",
  ui_story_5001_50010601_24_dialog_content = "Dia tidak sendirian, sial... Dia milikku <color=#FFB400>adik perempuan</color>!",
  ui_story_5001_50010601_25_dialog_content = "Eh? Adikmu?!",
  ui_story_5001_50010601_26_dialog_content = "Sekarang di mana dia?",
  ui_story_5001_50010601_27_dialog_content = "Dia aman di Colossus. Kami membawanya kembali ke Illumina untuk perawatan medis.",
  ui_story_5001_50010601_28_dialog_content = "Aku senang mendengar dia aman.",
  ui_story_5001_50010601_29_dialog_content = "Tidak bisa mengatakan saya tidak tersentuh oleh kebaikan Anda, tetapi Anda tidak tahu bahaya apa yang akan Anda hadapi dengan melakukan itu.",
  ui_story_5001_50010601_30_dialog_content = "Lagi pula, tidak mungkin aku membiarkan siapa pun mengambil adik perempuanku.",
  ui_story_5001_50010601_31_option_content = "Maaf, tapi aku tidak percaya padamu",
  ui_story_5001_50010601_32_dialog_content = "Kakak macam apa yang akan seperti ini terhadap adik perempuannya sendiri?",
  ui_story_5001_50010601_33_option_content = [[
Anda hanya ingin 
menguncinya lagi, bukan?]],
  ui_story_5001_50010601_34_dialog_content = "Aku melihat semuanya, Sinsa. Saya melihat di mana dia ditahan.",
  ui_story_5001_50010601_35_dialog_content = "Bagaimana orang bisa menguncinya seperti itu...",
  ui_story_5001_50010601_36_dialog_content = "Mari saya jelaskan.",
  ui_story_5001_50010601_37_dialog_content = "Apa yang Anda \"lihat\" adalah <color=#FFB400>ruang isolasi</color>. Hawa berbahaya bagi dirinya sendiri, dan semua orang di sekitarnya, jika dia keluar.",
  ui_story_5001_50010601_38_dialog_content = "Anda tidak akan mengerti situasinya.",
  ui_story_5001_50010601_39_dialog_content = "Tabung dan instrumen itu membuatnya tetap hidup... menjaga kondisinya agar tidak memburuk.",
  ui_story_5001_50010601_40_dialog_content = "Pada saat yang sama, itu membuat orang-orang di sekitarnya tetap aman.",
  ui_story_5001_50010601_41_dialog_content = "<color=#FFB400>Bahaya</color>? Bahaya apa?",
  ui_story_5001_50010601_42_dialog_content = "Ada apa sebenarnya dengan Hawa, Sinsa?",
  ui_story_5001_50010601_43_dialog_content = "Cukup.",
  ui_story_5001_50010601_44_dialog_content = "Seperti yang saya katakan, itu bukan urusan Anda. Saya sudah mengatakan cukup.",
  ui_story_5001_50010601_45_dialog_content = "Lalu bagaimana Anda menjelaskan Eclipsites di Tail Street?",
  ui_story_5001_50010601_46_dialog_content = "gerhana? Maksudmu hari ini lebih awal?",
  ui_story_5001_50010601_47_dialog_content = "Itu pasti karena masalah dengan ruang isolasi. Jika tidak...",
  ui_story_5001_50010601_48_dialog_content = "Jika Hawa benar-benar adik perempuanmu, bagaimana kamu bisa meninggalkannya sendirian di tempat yang berbahaya seperti itu?!",
  ui_story_5001_50010601_49_dialog_content = "Anda pasti suka omong kosong, bukan? Sudah kubilang, itu bukan urusanmu, jadi biarkan saja!",
  ui_story_5001_50010601_50_dialog_content = "Sekarang, apakah Anda akan menyerahkannya atau apa?!",
  ui_story_5001_50010601_51_dialog_content = "Kepercayaan diperoleh, Sinsa, bukan diberikan. Penjelasan dan tindakan Anda lebih dari cukup untuk membuat kami mencurigai Anda.",
  ui_story_5001_50010601_52_dialog_content = "Hawa sangat membutuhkan bantuan. Jika Anda tidak dapat membuktikan bahwa dia adalah saudara perempuan Anda, saya tidak punya pilihan selain membawanya kembali ke Illumina untuk perawatan.",
  ui_story_5001_50010601_53_dialog_content = "Illumina?",
  ui_story_5001_50010601_54_dialog_content = "Heh... Illumina memberitahu kita hal yang sama sebelumnya.",
  ui_story_5001_50010601_55_dialog_content = "Hah?",
  ui_story_5001_50010601_56_dialog_content = "Tunggu, apa artinya itu? Jelaskan dirimu!",
  ui_story_5001_50010601_57_dialog_content = "Bos! Saya pikir Anda perlu memeriksa ini!",
  ui_story_5001_50010601_58_dialog_content = "Graagh!!",
  ui_story_5001_50010601_59_dialog_content = "!!!",
  ui_story_5001_50010601_60_dialog_content = "Mengapa ada begitu banyak Eclipsites di sini, tiba-tiba?",
  ui_story_5001_50010601_61_dialog_content = "Mereka telah ditarik ke sini. Kotoran!",
  ui_story_5001_50010601_62_dialog_content = "Mereka benar-benar tidak memberi kita banyak waktu, apakah mereka...",
  ui_story_5001_50010601_63_dialog_content = "PlayerName! Bersiaplah untuk bertarung!",
  ui_story_5001_50010602_1_dialog_content = "...",
  ui_story_5001_50010602_2_dialog_content = "(Eclipsian) Dia... memiliki aroma Aurorian.",
  ui_story_5001_50010602_3_dialog_content = "?",
  ui_story_5001_50010602_4_dialog_content = "(Eclipsian) Cukup pertanyaan! Kita harus mematuhi perintah kita!",
  ui_story_5001_50010602_5_dialog_content = "...",
  ui_story_5001_50010602_6_dialog_content = "(Eclipsian) Saya akan menarik perhatian mereka. Anda membawanya pergi.",
  ui_story_5001_50010602_7_dialog_content = "(Eclipsian) Jangan biarkan dia datang untuk menyakiti.",
  ui_story_5001_50010602_8_dialog_content = "(Eclipsian) Kamu terlalu banyak bicara.",
  ui_story_5001_50010602_9_dialog_content = "(Eclipsian) Beli waktu sebanyak mungkin untuk kita!",
  ui_story_5001_50010602_10_dialog_content = "(Eclipsian) Mereka kuat. Saya akan melakukan apa yang saya bisa.",
  ui_story_5001_50010602_11_dialog_content = "(Eclipsian) Pukul di sini, atau kembali dan pecahkan kepalamu oleh Dawn. Pilihannya jelas.",
  ui_story_5001_50010602_12_dialog_content = "!!",
  ui_story_5001_50010602_13_dialog_content = "(Eclipsian) Aurorian... sedang bereaksi?",
  ui_story_5001_50010602_14_dialog_content = "...",
  ui_story_5001_50010702_1_dialog_content = "Hmm? Mereka sudah mundur? Kami baru saja memulai...",
  ui_story_5001_50010702_2_dialog_content = "Hai!! Aku belum selesai meledakkan kalian semua!!",
  ui_story_5001_50010702_3_dialog_content = "Biarkan saja, Joanie. Bos tidak ingin kita melakukan apa pun pada Colossus ini, ingat?",
  ui_story_5001_50010702_4_dialog_content = "Tapi aku tidak melakukan apa-apa!",
  ui_story_5001_50010702_5_dialog_content = "Lalu apa yang Anda sebut itu sekarang?",
  ui_story_5001_50010702_6_dialog_content = "Katakan, di mana bosnya?",
  ui_story_5001_50010702_7_dialog_content = "<color=#e8d9bb>Di dalam Colossus, di kamar Hawa</color>",
  ui_story_5001_50010702_8_dialog_content = "...",
  ui_story_5001_50010702_10_dialog_content = "Di mana dia?",
  ui_story_5001_50010702_11_dialog_content = "<size=45>Dimana adikku?!</size>",
  ui_story_5001_50010702_12_dialog_content = "Sinsa! Lepaskan PlayerName!",
  ui_story_5001_50010702_13_dialog_content = "Aku... sudah bilang... Dia ada di sini sebelumnya, tapi barusan...",
  ui_story_5001_50010702_14_dialog_content = "Rooting mereka semua! Jangan biarkan mereka berada di dekat Colossus!",
  ui_story_5001_50010702_15_dialog_content = "Kalian menonton sisi lain dari Colossus! Jangan biarkan salah satu dari mereka masuk ke dalam!",
  ui_story_5001_50010702_16_dialog_content = "Ikutlah denganku, PlayerName. Eclipsites terus bertambah jumlahnya!",
  ui_story_5001_50010702_17_dialog_content = "Kau yakin Eve akan aman di salah satu ruangan ini, Caelestite? Anda bersumpah?",
  ui_story_5001_50010702_18_dialog_content = "Aku bersumpah! Soroz sudah mengunci setiap kamar. Pintunya hanya bisa dibuka dari dalam sekarang...",
  ui_story_5001_50010702_19_dialog_content = "Tolong cepat kembali, PlayerName!",
  ui_story_5001_50010702_20_dialog_content = "Ada apa, Soroz?",
  ui_story_5001_50010702_21_dialog_content = "Gadis itu...",
  ui_story_5001_50010702_22_dialog_content = "Dia membuka pintu kamarnya!!",
  ui_story_5001_50010702_23_dialog_content = "Apakah Anda bercanda? Kau bilang padaku Eve pergi sendirian?!",
  ui_story_5001_50010702_24_dialog_content = "Itu kebenaran! Mungkin seseorang datang untuknya, seseorang yang dia kenal?",
  ui_story_5001_50010702_25_dialog_content = "Kalau tidak, tidak mungkin dia membuka pintu sendiri!",
  ui_story_5001_50010702_26_dialog_content = "Itu adalah Eclipsites, PlayerName. Eve pergi dengan beberapa dari mereka.",
  ui_story_5001_50010702_27_dialog_content = "gerhana? Saya tidak berpikir Sinsa akan percaya bahwa ...",
  ui_story_5001_50010702_28_dialog_content = "Percaya apa?",
  ui_story_5001_50010702_29_dialog_content = "Bos! Seseorang di sini punya sesuatu yang penting untuk memberitahu Anda!",
  ui_story_5001_50010702_30_dialog_content = "Malam! Hawa sudah pergi! Argh... Lukaku terbuka...",
  ui_story_5001_50010702_31_dialog_content = "Maksud kamu apa? Muntahkan!",
  ui_story_5001_50010702_32_dialog_content = "Ketika saya melawan Eclipsites... yah, saya menggigit sedikit lebih banyak daripada yang bisa saya kunyah, jadi saya berlari di belakang Colossus, dan saya melihat Hawa!",
  ui_story_5001_50010702_33_dialog_content = "Dia berjalan pergi dengan beberapa Eclipsites! Saya pikir mereka pergi ke utara! Atau apakah itu selatan?",
  ui_story_5001_50010702_34_dialog_content = "Argh! Berpikir lebih keras, dasar brengsek!!",
  ui_story_5001_50010702_35_dialog_content = "Aku serius, aku tidak ingat! Tepat setelah saya melihat mereka, Eclipsite lain membuat saya pingsan! Saya masih melihat ganda ...",
  ui_story_5001_50010702_36_dialog_content = "Apa yang kita lakukan, bos?",
  ui_story_5001_50010702_37_dialog_content = "Semuanya, berpisah dan cari! Jangan biarkan satu batu pun terlewat! Saya ingin orang-orang menyebar ke segala arah!",
  ui_story_5001_50010702_38_dialog_content = "Jika kami tidak menemukan Hawa di penghujung hari, tidak ada dari kalian yang akan berhasil keluar dari Gurun Rediesel!!",
  ui_story_5001_50010801_1_dialog_content = "...",
  ui_story_5001_50010801_2_dialog_content = "...",
  ui_story_5001_50010801_3_dialog_content = "...",
  ui_story_5001_50010801_4_dialog_content = "Haruskah kita mencari lebih jauh ke arah utara, PlayerName? Saya belum mendeteksi jejak gadis itu.",
  ui_story_5001_50010801_5_dialog_content = "Suasana di sini sepertinya agak... canggung.",
  ui_story_5001_50010801_6_dialog_content = "Tak perlu.",
  ui_story_5001_50010801_7_option_content = "Katakan sesuatu untuk memecahkan ketegangan",
  ui_story_5001_50010801_8_dialog_content = "Sinsa.",
  ui_story_5001_50010801_9_dialog_content = "...",
  ui_story_5001_50010801_10_dialog_content = "Kita akan menemukan Hawa. Aku yakin itu.",
  ui_story_5001_50010801_11_dialog_content = "Tutup mulut bodohmu! Jika bukan karena Anda, Eve tidak akan berada dalam kekacauan ini sekarang!",
  ui_story_5001_50010801_12_option_content = "Jangan katakan apa-apa",
  ui_story_5001_50010801_13_dialog_content = "...",
  ui_story_5001_50010801_14_dialog_content = "...",
  ui_story_5001_50010801_15_dialog_content = "Apa yang kamu lihat?",
  ui_story_5001_50010801_16_dialog_content = "Hei, aku hanya melihat ke arahmu, itu saja! Saya tidak mengatakan apa-apa!",
  ui_story_5001_50010801_17_dialog_content = "Tutup perangkap Anda, jika Anda tahu apa yang baik untuk Anda. Aku sangat marah sekarang, dan aku bertanggung jawab untuk menghancurkan kepalamu seperti melon.",
  ui_story_5001_50010801_18_dialog_content = "Berhenti menyerangku, ya? Tidakkah menurutmu cara terbaik kita untuk menemukan Hawa adalah dengan bekerja sama?",
  ui_story_5001_50010801_19_dialog_content = "Anda punya beberapa bola, nak. Jika bukan karena Anda, Eve tidak akan berada dalam kekacauan ini sekarang!",
  ui_story_5001_50010801_20_dialog_content = "Oh tidak, aku tidak akan membiarkanmu memutarbalikkan kebenaran lagi.",
  ui_story_5001_50010801_21_dialog_content = "Jika kita tidak muncul di Tail Street saat kita melakukannya, Eclipsites itu akan...",
  ui_story_5001_50010801_22_dialog_content = "Anda tidak tahu apa-apa.",
  ui_story_5001_50010801_23_dialog_content = "Tidakkah kamu tahu bagaimana berbicara tanpa mengumpat?",
  ui_story_5001_50010801_24_dialog_content = "CUKUP, kalian berdua! Berikan istirahat, sudah!",
  ui_story_5001_50010801_25_dialog_content = "Anda membutuhkan Colossus untuk membantu Anda menemukan Hawa, bukan Sinsa? Dalam hal ini, saya sarankan Anda bekerja sama dan menyimpan pertengkaran untuk nanti.",
  ui_story_5001_50010801_26_dialog_content = "Aku tidak bertengkar! Selain itu, Caelestite memulainya...",
  ui_story_5001_50010801_27_dialog_content = "Kau…!",
  ui_story_5001_50010801_28_dialog_content = "Bos! The Canaries baru saja melaporkan sejumlah Eclipsites bepergian menuju <color=#FFB400>Ngarai Mata Merah</color>!",
  ui_story_5001_50010801_29_dialog_content = "<color=#FFB400>Ngarai Mata Merah</color>? Tapi bagaimana caranya...",
  ui_story_5001_50010801_30_dialog_content = "Argh, mengerti! Awasi mereka, dan beri tahu saya segera jika mereka membuat gerakan lucu!",
  ui_story_5001_50010801_31_dialog_content = "Baiklah Caelestite, bawa kami ke Red-Eye Gorge!",
  ui_story_5001_50010801_32_dialog_content = "D-Apakah kamu tidak ingin menunggu yang lain, bos?",
  ui_story_5001_50010801_33_dialog_content = "Tidak. Kami pergi sekarang.",
  ui_story_5001_50010801_34_dialog_content = "Tapi bagaimana kita bisa melewati badai? Saya pikir kita harus menunggu yang lain juga...",
  ui_story_5001_50010801_35_dialog_content = "<color=#FFB400>Badai</color>? Terbang langsung? Apa yang kalian bicarakan?",
  ui_story_5001_50010801_36_dialog_content = "Lepidoz tidak akan bisa masuk, jadi tidak ada gunanya menunggu mereka. Kita hanya perlu terbang langsung dengan Colossus ini.",
  ui_story_5001_50010801_37_dialog_content = "Boss... Badai itu akan menghancurkan Colossus ini!",
  ui_story_5001_50010801_38_dialog_content = "Merobeknya?! Sekarang tunggu sebentar! Anda sebaiknya memberitahu saya apa sih yang Anda rencanakan!",
  ui_story_5001_50010801_39_dialog_content = "Ah, Anda akan lihat ketika kita sampai di sana. Selain itu, Anda harus mendengarkan saya dengan cara apa pun.",
  ui_story_5001_50010801_40_dialog_content = "Jika Anda punya rencana, Sinsa, Anda harus memberi tahu kami sekarang. Soroz juga butuh waktu untuk bersiap!",
  ui_story_5001_50010801_41_dialog_content = "Kalau tidak, jika terjadi kesalahan, siapa lagi yang akan membantu Hawa?",
  ui_story_5001_50010801_42_dialog_content = "...",
  ui_story_5001_50010801_43_dialog_content = "Aku hanya akan mengatakannya sekali.",
  ui_story_5001_50010801_44_dialog_content = "Red-Eye Gorge adalah tempat pegunungan terjal yang dikelilingi oleh badai besar.",
  ui_story_5001_50010801_46_dialog_content = "Jika Eve benar-benar pergi ke sana... Tidak, bahkan aku tidak tahu bagaimana dia bisa masuk.",
  ui_story_5001_50010801_47_dialog_content = "Jadi kau ingin aku mengemudikan Soroz melewati badai?",
  ui_story_5001_50010801_48_dialog_content = "Betul sekali. Ada keberatan?",
  ui_story_5001_50010801_49_dialog_content = "...",
  ui_story_5001_50010801_50_dialog_content = "Tidak. Tapi aku hanya setuju demi Hawa, bukan demi kamu.",
  ui_story_5001_50010801_51_dialog_content = "Ini tidak berarti kami menyerahkannya padamu setelah ini selesai.",
  ui_story_5001_50010801_52_dialog_content = "Kau…!",
  ui_story_5001_50010801_53_dialog_content = "Jangan lupa, ini ColossusKU, dan kita cukup tinggi sekarang.",
  ui_story_5001_50010801_55_dialog_content = "Apakah Anda mengancam saya ?!",
  ui_story_5001_50010801_56_dialog_content = "Memangnya kamu tidak khawatir?",
  ui_story_5001_50010801_57_dialog_content = "Jangan khawatir. Jika terjadi sesuatu pada Eve, aku pasti akan membuatmu membayar...",
  ui_story_5001_50010801_58_dialog_content = "Sekali lagi, kalian berdua? Kurangi berdebat, lebih banyak menyelamatkan!",
  ui_story_5001_50010801_59_dialog_content = "Lagi pula, kita semua... eh, di tim yang sama sekarang.",
  ui_story_5001_50010801_60_dialog_content = "Itu berarti Anda adalah rekan satu tim, dan tidak ada pembunuhan tim dalam misi ini. Mengerti?",
  ui_story_5001_50010801_61_dialog_content = "Sekeren kamu barusan, PlayerName, harap bersikap realistis dan ingat bahwa kita tidak bisa mengalahkannya sekarang.",
  ui_story_5001_50010801_62_dialog_content = "Cih.",
  ui_story_5001_50010801_63_dialog_content = "Kita harus bertukar informasi sebelum sampai ke Red-Eye Gorge.",
  ui_story_5001_50010801_64_dialog_content = "Sejujurnya, saya tahu Hawa istimewa sejak awal. Dia mengeluarkan perasaan misterius yang hampir tak terlukiskan ini.",
  ui_story_5001_50010801_65_dialog_content = "Ini lebih sederhana dari yang Anda pikirkan. <color=#FFB400>Hawa dapat menarik Eclipsites</color>.",
  ui_story_5001_50010801_66_dialog_content = "Tubuhnya terus-menerus mengeluarkan <color=#FFB400>aroma yang unik</color>, yang merupakan bagian dari mengapa saya harus melindunginya dengan cara apa pun.",
  ui_story_5001_50010801_67_dialog_content = "Masalahnya, Eclipsites yang dia tarik tidak akan menyerangnya dengan sendirinya.",
  ui_story_5001_50010801_68_dialog_content = "Lalu mengapa mereka terus-menerus mengejarnya, dan bahkan mencoba mengambilnya?",
  ui_story_5001_50010801_69_dialog_content = "Aku pun tidak tahu jawabannya.",
  ui_story_5001_50010801_70_dialog_content = "Dan…",
  ui_story_5001_50010801_71_dialog_content = "Mengapa Ngarai Mata Merah juga?",
  ui_story_5001_50010801_73_dialog_content = "Sudah setengah jam... Bagaimana kita masih belum selesai?",
  ui_story_5001_50010801_74_dialog_content = "Badai lebih luas dari yang saya perkirakan. Dibutuhkan semua kekuatan saya hanya untuk menjaga keseimbangan.",
  ui_story_5001_50010801_75_dialog_content = "Satu-satunya pilihan saya adalah mengikuti rotasi badai dan berusaha menerobos. Semuanya, persiapkan dirimu!",
  ui_story_5001_50010801_76_dialog_content = "Pegang sesuatu, semuanya.",
  ui_story_5001_50010801_77_dialog_content = "Colossus ini... Itu, eh, tidak memiliki sabuk pengaman...",
  ui_story_5001_50010801_78_dialog_content = "Saya tidak perlu Anda mengatakan itu! Tunggu saja, setelah ini selesai, bahkan toilet akan memiliki sabuk pengaman ...",
  ui_story_5001_50010801_79_dialog_content = "Tunggu, semuanya!",
  ui_story_5001_50010801_80_dialog_content = "Wah! Apakah kita tersambar petir? Dindingnya mulai bocor!",
  ui_story_5001_50010801_81_dialog_content = "Kita tidak akan mati di sini, kan?!",
  ui_story_5001_50010801_82_dialog_content = "Tidak bisakah Anda setidaknya MENCOBA untuk menjadi lebih positif?!",
  ui_story_5001_50010801_83_dialog_content = "Hei, mata ke depan! Anda pilotnya, bukan? Lakukan sesuatu!",
  ui_story_5001_50010801_84_dialog_content = "Saya melakukan yang terbaik sekarang! Kaulah yang menggangguku!",
  ui_story_5001_50010801_85_dialog_content = "Rusak! Kita akan dicabik-cabik!",
  ui_story_5001_50010801_86_dialog_content = "Biarkan saya membantu Anda, PlayerName!",
  ui_story_5001_50010801_87_dialog_content = "Lihat di depan kita!!",
  ui_story_5001_50010801_88_dialog_content = "Langit... Semakin cerah?",
  ui_story_5001_50010801_89_dialog_content = "Kita berhasil.",
  ui_story_5001_50010801_90_dialog_content = "Ngarai Mata Merah...",
  ui_story_5001_50010801_91_dialog_content = "PlayerName, mesin saya mengalami kerusakan parah. Mencoba mengaktifkannya kembali sekarang...",
  ui_story_5001_50010801_92_dialog_content = "Pengaktifan ulang gagal. Sepertinya mesin saya telah terbakar.",
  ui_story_5001_50010801_93_dialog_content = "... Tidak apa-apa, ayo lakukan pendaratan darurat. Kamu sudah melalui lebih dari cukup, Soroz.",
  ui_story_5001_50010801_94_dialog_content = "Apakah ada yang terluka?",
  ui_story_5001_50010801_95_dialog_content = "Ow ... Uji coba Anda benar-benar sesuatu ...",
  ui_story_5001_50010801_96_dialog_content = "Anda bisa membuat Bopper kabur demi uangnya... Tidak, saya pikir Anda bahkan mungkin lebih buruk...",
  ui_story_5001_50010801_97_dialog_content = "Jika otak saya tidak begitu digoreng sekarang, saya akan memberitahu Anda ...",
  ui_story_5001_50010801_98_dialog_content = "Apakah kamu baik-baik saja, Soroz?",
  ui_story_5001_50010801_99_dialog_content = "Saya terlalu sering disambar petir. Sistem saya rusak berat.",
  ui_story_5001_50010801_100_dialog_content = "Pergi. Cari gadis itu. Saya akan meminta Fireflies melakukan perawatan darurat saat Anda pergi.",
  ui_story_5001_50010801_101_dialog_content = "Dipahami. Panggil aku jika kamu butuh sesuatu.",
  ui_story_5001_50010801_102_dialog_content = "Saya akan baik-baik saja. Aman, semuanya.",
  ui_story_5001_50010801_103_dialog_content = "Eh... Sepertinya kita akan menghabiskan banyak uang untuk perbaikan lagi...",
  ui_story_5001_50010801_104_dialog_content = "Hei Vice, apa itu di tanganmu?",
  ui_story_5001_50010801_105_dialog_content = "Ini? Hanya beberapa bagian yang jatuh tadi. Sepertinya kita tidak bisa menggunakannya lagi di Soroz.",
  ui_story_5001_50010801_106_dialog_content = "Tapi aku punya ide! Mari kita ambil beberapa potong lagi untuk membantu menguatkan diri kita melawan angin!",
  ui_story_5001_50010801_107_dialog_content = "Tidak ada angin.",
  ui_story_5001_50010801_108_dialog_content = "Hah?",
  ui_story_5001_50010801_109_dialog_content = "Buka pintunya dan lihat sendiri. <color=#FFB400>Kami berada di mata badai</color>.",
  ui_story_5001_50010801_110_dialog_content = "Ini adalah...!",
  ui_story_5001_50010801_111_dialog_content = "Lihatlah ukuran ngarai! Ini praktis ngarai!",
  ui_story_5001_50010801_112_dialog_content = "Dan sepertinya ada jalan di tengah juga. Apakah itu alami atau buatan manusia, saya bertanya-tanya?",
  ui_story_5001_50010801_113_dialog_content = "Lihatlah ke langit, Wakil. Ini cerah dan cerah tepat di atas mata badai.",
  ui_story_5001_50010801_114_dialog_content = "Apa tempat yang menakjubkan...",
  ui_story_5001_50010801_115_dialog_content = "Saya tidak pernah menyangka lingkungan unik seperti itu bisa berada di dalam badai seperti ini.",
  ui_story_5001_50010801_116_dialog_content = "Dan di sana! Apakah itu jejak a <color=#FFB400>Desa kecil</color>?",
  ui_story_5001_50010801_117_dialog_content = "Mereka adalah... Apakah orang dulu tinggal di sini?",
  ui_story_5001_50010801_118_dialog_content = "Sekitar dua puluh tahun yang lalu, ya.",
  ui_story_5001_50010801_119_dialog_content = "Desa ini dulunya jauh lebih besar dari yang Anda bayangkan. Reruntuhan ini adalah semua yang tersisa, sekarang ...",
  ui_story_5001_50010801_120_dialog_content = "Tidak pernah berpikir saya akan kembali suatu hari nanti, tetapi inilah saya.",
  ui_story_5001_50010801_121_dialog_content = "Sinsa... Maksudmu...",
  ui_story_5001_50010801_122_dialog_content = "Mmhm. Tempat ini dulu...",
  ui_story_5001_50010801_123_dialog_content = "Milikku dan Hawa <color=#FFB400>kampung halaman</color>.",
  ui_story_5001_50010901_1_dialog_content = "Tunggu... Aku terus merasa bahwa kita sedang diawasi oleh seseorang... Atau sesuatu.",
  ui_story_5001_50010901_2_dialog_content = "Eclipsite?",
  ui_story_5001_50010901_3_dialog_content = "Tidak ada ide. Kepalaku benar-benar sakit, tapi tidak terasa seperti kelebihan beban... Mungkin aku dipukul lebih awal?",
  ui_story_5001_50010901_4_dialog_content = "Badai ini menakutkan... Saya hampir tidak percaya orang akan memilih untuk tinggal di sini.",
  ui_story_5001_50010901_5_dialog_content = "Red-Eye Gorge tidak selalu dikelilingi oleh badai aneh ini, kau tahu?",
  ui_story_5001_50010901_6_dialog_content = "Tapi suatu hari... entah dari mana.",
  ui_story_5001_50010901_7_dialog_content = "Apakah itu sebabnya desa seperti ini sekarang? Karena badai?",
  ui_story_5001_50010901_15_dialog_content = "Iya dan tidak.",
  ui_story_5001_50010901_16_dialog_content = "Lihat lubang besar di sana? Percaya atau tidak...",
  ui_story_5001_50010901_17_dialog_content = "Ini adalah gunung berapi.",
  ui_story_5001_50010901_18_dialog_content = "Desa ini dibangun di dekat kawah gunung berapi?! Apakah penduduk desa tahu?",
  ui_story_5001_50010901_19_dialog_content = "Tidak, mereka tidak... Atau setidaknya, mereka tidak tahu itu akan meletus seperti hari itu.",
  ui_story_5001_50010901_20_dialog_content = "Dua puluh tahun yang lalu, segerombolan Eclipsites menyerang desa. Sementara seluruh ngarai berantakan, gunung berapi...",
  ui_story_5001_50010901_21_dialog_content = "Pilih waktu yang tepat untuk meletus.",
  ui_story_5001_50010901_22_dialog_content = "Lava tidak sampai ke tempat kita sekarang, tetapi tidak lama kemudian asap dan abu menelan ngarai.",
  ui_story_5001_50010901_23_dialog_content = "Kemudian, begitu menutupi langit, hujan sehitam gulita mengguyur kami. Selama berminggu-minggu, itu jatuh dan jatuh ...",
  ui_story_5001_50010901_24_dialog_content = "Hari dimana semuanya dimulai juga merupakan hari dimana badai muncul, memisahkan kita dari dunia luar.",
  ui_story_5001_50010901_25_dialog_content = "Pada akhirnya, sebagian besar penduduk desa tidak bisa datang, dan Red-Eye Gorge menjadi seperti sekarang ini.",
  ui_story_5001_50010901_26_dialog_content = "Aku turut sedih...",
  ui_story_5001_50010901_27_dialog_content = "Tapi lihat, gunung berapi yang sama yang menghancurkan desa itu sekarang menjadi sumber kehidupan bagi makhluk-makhluk yang tinggal di sini!",
  ui_story_5001_50010901_28_dialog_content = "Makhluk-makhluk yang hidup di sini...",
  ui_story_5001_50010901_29_dialog_content = "Dan Anda tidak berpikir itu termasuk kami?",
  ui_story_5001_50010901_30_dialog_content = "Saya hampir bisa merasakan ironi...",
  ui_story_5001_50010901_31_dialog_content = "Sinsa, di belakangmu!",
  ui_story_5001_50010901_32_dialog_content = "Graaaah!",
  ui_story_5001_50010901_33_dialog_content = "Bagaimana bisa Eclipsites mendekati tempat seperti ini?",
  ui_story_5001_50010901_34_dialog_content = "Atau mungkin... mereka selalu tinggal di sini?",
  ui_story_5001_50010901_35_dialog_content = "Desa saya dihancurkan oleh gunung berapi DAN bajingan busuk ini.",
  ui_story_5001_50010901_37_dialog_content = "Alam adalah alam, tidak ada gunanya menyalahkannya.",
  ui_story_5001_50010901_38_dialog_content = "Tapi gerhana...",
  ui_story_5001_50010901_39_dialog_content = "Adalah cerita yang berbeda!!!",
  ui_story_5001_50010902_1_dialog_content = "Bicaralah!",
  ui_story_5001_50010902_2_dialog_content = "Anda membawa seorang gadis kecil ke sini, bukan?!",
  ui_story_5001_50010902_3_dialog_content = "Urraagh…",
  ui_story_5001_50010902_4_dialog_content = "Apa itu? Ugh, katakan sesuatu yang bisa aku mengerti, sial!",
  ui_story_5001_50010902_5_dialog_content = "Astaga!!!",
  ui_story_5001_50010902_6_dialog_content = "Mungkinkah Eclipsite ini belum mempelajari Semesta?",
  ui_story_5001_50010902_7_dialog_content = "Sialan!",
  ui_story_5001_50010902_8_dialog_content = "Maka itu sama saja dengan mati bagiku!",
  ui_story_5001_50010902_9_dialog_content = "Hraaooh!!",
  ui_story_5001_50010902_10_dialog_content = "Saya pikir kita harus berpisah dan mencari, bos.",
  ui_story_5001_50010902_11_dialog_content = "Ngarai Mata Merah sangat besar. Pada tingkat kita akan ...",
  ui_story_5001_50010902_12_dialog_content = "Dia ada benarnya. Kita perlu menyebar dan menutupi lebih banyak tanah.",
  ui_story_5001_50010902_13_dialog_content = "PlayerName tidak memiliki kemampuan tempur, jadi kami akan mencari sebagai duo.",
  ui_story_5001_50010902_14_dialog_content = "Tidak ada kesempatan! Bagaimana kami tahu Anda tidak akan lari begitu saja?",
  ui_story_5001_50010902_15_dialog_content = "Anda benar-benar berpikir kami dalam posisi untuk melarikan diri di tempat seperti ini?",
  ui_story_5001_50010902_16_dialog_content = "Seperti yang saya katakan, kita akan menemukan Hawa.",
  ui_story_5001_50010902_17_dialog_content = "Bahkan jika kami bisa melarikan diri, kami hanya akan lari jika ada Hawa bersama kami.",
  ui_story_5001_50010902_18_dialog_content = "Kami hanya mungkin, jika Soroz dapat menyelesaikan perbaikan segera.",
  ui_story_5001_50010902_19_dialog_content = "Ya ya, jangan terlalu sombong ...",
  ui_story_5001_50010902_20_dialog_content = "Baiklah, itu cukup! PlayerName dan saya akan mencari reruntuhan. Regina, kamu dan Vice pergi melihat-lihat gunung berapi.",
  ui_story_5001_50010902_21_dialog_content = "Jika Anda menemukan sesuatu, hubungi kami segera!",
  ui_story_5001_50010902_22_dialog_content = "Tapi bos, udang itu tidak bisa bertarung! Anda akan baik-baik saja sendiri?",
  ui_story_5001_50010902_23_dialog_content = "Anda ingin bekerja sama dengan udang ini?",
  ui_story_5001_50010902_24_dialog_content = "T-Tidak apa-apa. Ayo, nona kecil dari Illumina, kita berangkat.",
  ui_story_5001_50010902_25_dialog_content = "Nama saya Wakil.",
  ui_story_5001_50010902_26_dialog_content = "Ha! Seperti itu penting!",
  ui_story_5001_50010902_27_dialog_content = "Jangan terlalu dekat ke tepi. Batuan lava hampir tidak stabil seperti yang Anda pikirkan.",
  ui_story_5001_50010902_28_dialog_content = "Anda mengerti, bos! Perhatikan punggungmu!",
  ui_story_5001_50010902_29_dialog_content = "Ayo pergi, Caelestit.",
  ui_story_5001_50010902_30_dialog_content = "...",
  ui_story_5001_50010902_31_dialog_content = "PlayerName…",
  ui_story_5001_50010902_32_dialog_content = "Tidak apa-apa, Wakil. Jaga dirimu baik-baik.",
  ui_story_5001_50010902_33_dialog_content = "... Kamu juga.",
  ui_story_5001_50010902_34_dialog_content = "Saya akan. Sinsa mungkin kasar, tapi dia tidak sepenuhnya tidak masuk akal.",
  ui_story_5001_50010902_35_dialog_content = "Aku hanya ingin melemparkanmu ke gunung berapi itu...",
  ui_story_5001_50010902_36_dialog_content = "Memangnya kamu tidak khawatir?",
  ui_story_5001_50011001_1_dialog_content = "<color=#e8d9bb>Di Reruntuhan Ngarai Mata Merah</color>",
  ui_story_5001_50011001_2_dialog_content = "Cara ini.",
  ui_story_5001_50011001_3_dialog_content = "Ya.",
  ui_story_5001_50011001_4_dialog_content = "Perhatikan langkahmu.",
  ui_story_5001_50011001_5_dialog_content = "Tentu.",
  ui_story_5001_50011001_6_dialog_content = "Bisakah kamu menyeberang?",
  ui_story_5001_50011001_7_dialog_content = "Mereka hanya retakan di tanah. Saya akan baik-baik saja.",
  ui_story_5001_50011001_8_dialog_content = "Batu itu cukup longgar. Awas.",
  ui_story_5001_50011001_9_dialog_content = "Terima kasih.",
  ui_story_5001_50011001_10_dialog_content = "Jangan khawatir.",
  ui_story_5001_50011001_11_dialog_content = "...",
  ui_story_5001_50011001_12_dialog_content = "...",
  ui_story_5001_50011001_13_dialog_content = "Hei... Sinsa?",
  ui_story_5001_50011001_14_dialog_content = "Silakan.",
  ui_story_5001_50011001_15_dialog_content = "Apakah Eve benar-benar adik perempuanmu?",
  ui_story_5001_50011001_16_dialog_content = "Ya.",
  ui_story_5001_50011001_17_dialog_content = "Kenapa aku harus memberitahumu berkali-kali?",
  ui_story_5001_50011001_18_dialog_content = "Apakah kita benar-benar terlihat berbeda satu sama lain?",
  ui_story_5001_50011001_19_option_content = "Y...Ya?",
  ui_story_5001_50011001_20_dialog_content = "Kami terlihat persis sama!",
  ui_story_5001_50011001_21_option_content = "Sama sekali tidak!",
  ui_story_5001_50011001_22_dialog_content = "Kalian berdua tidak terlihat sama! Anda tidak bisa terlihat lebih berbeda jika Anda mencoba!",
  ui_story_5001_50011001_23_dialog_content = "Mungkin Anda hanya perlu melihat lebih dekat, ya?",
  ui_story_5001_50011001_24_dialog_content = "<size=45>Aduh! Hentikan, kau hampir membuat bahuku terkilir!</size>",
  ui_story_5001_50011001_A1_dialog_content = "Lihat kemiripannya sekarang?",
  ui_story_5001_50011001_25_dialog_content = "Baik baik Baik! Jika dia benar-benar adikmu, aku akan minta maaf padamu.",
  ui_story_5001_50011001_26_dialog_content = "Hmph, asal kau tahu.",
  ui_story_5001_50011001_27_dialog_content = "Saya tidak kurang kesal dari sebelumnya, meskipun.",
  ui_story_5001_50011001_28_dialog_content = "Kecewa?",
  ui_story_5001_50011001_29_dialog_content = "Kenapa kau menguncinya sendirian di tempat seperti itu? Aku bisa merasakan bahwa dia sedang dipenjara di sana.",
  ui_story_5001_50011001_30_dialog_content = "Aku bahkan bisa merasakan apa yang dia rasakan! Rasa sakit, kesepian, ketakutan... Tapi dia tidak ingin menunjukkannya.",
  ui_story_5001_50011001_31_dialog_content = "Pernahkah terpikir oleh Anda mengapa Hawa begitu terpesona dengan dunia luar?",
  ui_story_5001_50011001_32_dialog_content = "Dia tahu itu tidak aman di luar sana, dan dia tahu kami orang asing, namun dia masih ikut dengan kami.",
  ui_story_5001_50011001_33_dialog_content = "...",
  ui_story_5001_50011001_34_dialog_content = "Ini bukan berita bagi saya, PlayerName.",
  ui_story_5001_50011001_35_dialog_content = "Jadi apa yang telah Anda lakukan tentang itu, \"kakak\"?",
  ui_story_5001_50011001_36_dialog_content = "Semuanya. Aku sudah melakukan... semua yang harus dilakukan.",
  ui_story_5001_50011001_37_dialog_content = "\"Semuanya,\" ya? Maksudnya apa?",
  ui_story_5001_50011001_38_dialog_content = "Anda tidak akan mengerti. Kamu bahkan tidak tahu apa yang terjadi padanya... Kamu bahkan tidak tahu...",
  ui_story_5001_50011001_39_dialog_content = "Apa yang telah dilakukan Rediesel Wrench untuknya selama ini...",
  ui_story_5001_50011001_40_dialog_content = "Jadi ceritakan tentang hal itu. Jika ada, Vice dan saya mungkin bisa membantu!",
  ui_story_5001_50011001_41_dialog_content = "...",
  ui_story_5001_50011001_42_dialog_content = "Alasan kenapa kamu masih tidak mempercayai kami... Apakah ini ada hubungannya dengan Illumina?",
  ui_story_5001_50011001_43_dialog_content = "Apa terjadi sesuatu antara kau dan...",
  ui_story_5001_50011001_44_dialog_content = "Astaga! Graaah!",
  ui_story_5001_50011001_45_dialog_content = "Tunggu!",
  ui_story_5001_50011001_46_dialog_content = "Bos bilang ... tidak diizinkan ... lanjut!",
  ui_story_5001_50011001_47_dialog_content = "Oh? Kedengarannya bagi saya seperti Anda menyembunyikan sesuatu di belakang sana ...",
  ui_story_5001_50011001_48_dialog_content = "Mungkin Hawa, Sinsa!",
  ui_story_5001_50011001_49_dialog_content = "T-Tidak! Tidak ada \"Hawa\" di depan!",
  ui_story_5001_50011001_50_dialog_content = "Ah, aku mengerti. Jadi, kau akan minggir atau aku harus membuatmu?",
  ui_story_5001_50011001_51_dialog_content = "Eclipsite ini... Kenapa rasanya seperti pernah melihatnya?",
  ui_story_5001_50011101_1_dialog_content = "Urrgh... Tidak ada pukulan... Tolong, jangan dipukul! Saya tidak tahu ... benar-benar ...",
  ui_story_5001_50011101_2_dialog_content = "Sebuah Eclipsite memohon belas kasihan? Ini adalah yang pertama...",
  ui_story_5001_50011101_3_dialog_content = "Tidak setiap hari kami menemukan satu yang dapat berbicara bahasa kami juga. Kita akan baik-baik saja, sobat...",
  ui_story_5001_50011101_4_dialog_content = "... Urgh.",
  ui_story_5001_50011101_5_dialog_content = "Nah, apakah Anda membawa seorang gadis kecil ke sini atau tidak?",
  ui_story_5001_50011101_6_dialog_content = "Cukup pendek, rambut panjang, imut seperti kancing?",
  ui_story_5001_50011101_7_dialog_content = "Tidak... aku... aku tidak tahu.",
  ui_story_5001_50011101_8_dialog_content = "Kamu yakin tentang itu?",
  ui_story_5001_50011101_9_dialog_content = "Mungkin kunci pas saya di sini bisa menggerakkan ingatan Anda?",
  ui_story_5001_50011101_10_dialog_content = "Urgh! Aku bicara! Dia adalah...",
  ui_story_5001_50011101_12_dialog_content = "S... Pelan-pelan, Sinsa! aku tidak bisa... teruskan...",
  ui_story_5001_50011101_13_dialog_content = "<color=#FFB400>Malam</color>!!!",
  ui_story_5001_50011101_14_dialog_content = "...",
  ui_story_5001_50011101_16_dialog_content = "Aku tidak bisa merasakan kehadirannya, Sinsa... Kurasa kesadarannya sedang ditekan, entah bagaimana!",
  ui_story_5001_50011101_17_dialog_content = "Malam! Aku di sini, Hawa!",
  ui_story_5001_50011101_18_dialog_content = "Graagh!!",
  ui_story_5001_50011101_19_dialog_content = "Pergi!",
  ui_story_5001_50011101_20_dialog_content = "Tunggu, Sinsa! Ini bisa jadi jebakan! \"Bos\" Eclipsite itu mungkin masih ada!",
  ui_story_5001_50011101_21_dialog_content = "...",
  ui_story_5001_50011101_22_dialog_content = "Siapa di sana?",
  ui_story_5001_50011101_23_dialog_content = "Mungkin dia juga diculik oleh Eclipsites?",
  ui_story_5001_50011101_24_dialog_content = "Saya tidak berpikir siapa pun yang gesit ini bisa diculik oleh siapa pun ...",
  ui_story_5001_50011101_25_dialog_content = "Hah? Maksudmu…",
  ui_story_5001_50011101_26_dialog_content = "...",
  ui_story_5001_50011101_27_dialog_content = "Tidak berbicara, ya? Baik menurut saya, saya juga bukan orang yang suka mengobrol.",
  ui_story_5001_50011101_28_dialog_content = "PlayerName! Temukan cara untuk mengeluarkan Hawa dari sini!",
  ui_story_5001_50011101_29_dialog_content = "Saya akan menarik perhatian yang satu ini.",
  ui_story_5001_50011101_30_dialog_content = "Mengerti! Aku akan memberi tahu Vice dan Regina, jadi mereka bisa bergegas ke sini!",
  ui_story_5001_50011101_31_dialog_content = "Ini hampir berakhir.",
  ui_story_5001_50011101_32_dialog_content = "Apa katamu?",
  ui_story_5001_50011101_33_dialog_content = "Tunggu sebentar lagi... Ini hampir berakhir.",
  ui_story_5001_50011101_34_dialog_content = "Apakah Anda mengerti apa yang dia katakan?",
  ui_story_5001_50011101_35_option_content = "Aku juga tidak mengerti.",
  ui_story_5001_50011101_36_dialog_content = "Ini tidak akan mudah... Cepat, ke belakangku!",
  ui_story_5001_50011101_37_option_content = "\"Ini hampir berakhir\"?",
  ui_story_5001_50011101_38_dialog_content = "Mungkin dia hanya berbicara dalam tidurnya atau sesuatu...",
  ui_story_5001_50011101_39_dialog_content = "Apapun itu, pergilah ke belakangku. Intuisiku mengatakan bahwa kita dalam masalah...",
  ui_story_5001_50011101_40_dialog_content = "Jangan... mendekat.",
  ui_story_5001_50011101_41_dialog_content = "Jangan berani...",
  ui_story_5001_50011101_42_dialog_content = "Dan bagaimana jika saya melakukannya, ya?",
  ui_story_5001_50011101_43_dialog_content = "Hentikan mereka!",
  ui_story_5001_50011101_44_dialog_content = "Graaaaaagh!!!",
  ui_story_5001_50011102_1_dialog_content = "PlayerName! Apakah kamu baik-baik saja?",
  ui_story_5001_50011102_2_dialog_content = "Ini malam!",
  ui_story_5001_50011102_3_dialog_content = "Tahan! Seseorang di sana bersama bos... Hei bos, siapa itu?",
  ui_story_5001_50011102_4_dialog_content = "Dia adalah \"bos\" dari Eclipsites ini.",
  ui_story_5001_50011102_5_dialog_content = "Ha? Gadis kecil ini?",
  ui_story_5001_50011102_6_dialog_content = "Mungkin dia adalah Eclipsite tingkat tinggi?",
  ui_story_5001_50011102_7_dialog_content = "Tidak... Tidak peduli bagaimana kamu melihatnya, dia adalah <color=#FFB400>aurora</color>.",
  ui_story_5001_50011102_8_dialog_content = "Tapi dia baru saja memerintahkan Eclipsites untuk menyerang kita!",
  ui_story_5001_50011102_9_dialog_content = "Mustahil... Seorang Aurorian yang bisa mengendalikan Eclipsites?",
  ui_story_5001_50011102_10_dialog_content = "Jika dia benar-benar seorang Aurorian, maka dilihat dari penampilannya... Dia seharusnya seumuran dengan Hawa, kan?",
  ui_story_5001_50011102_11_dialog_content = "...",
  ui_story_5001_50011102_12_dialog_content = "Sehat? Sudah cukup belum?",
  ui_story_5001_50011102_13_dialog_content = "Anda dapat memanggil seratus antek Anda lagi, dan mereka masih tidak akan mendapat kesempatan.",
  ui_story_5001_50011102_14_dialog_content = "Apa yang saya katakan adalah bahwa Eclipsites ini tidak layak diperjuangkan.",
  ui_story_5001_50011102_15_dialog_content = "Aku hanya ingin adik perempuanku kembali, tapi jika kamu tidak menyerahkannya... Aku tidak akan menunjukkan belas kasihan lagi padamu.",
  ui_story_5001_50011102_16_dialog_content = "Saya tidak membutuhkan perlindungan mereka.",
  ui_story_5001_50011102_17_dialog_content = "Mereka... tidak lain hanyalah boneka.",
  ui_story_5001_50011102_18_dialog_content = "Mereka tidak bisa mengalahkan saya, jadi mereka menyerah kepada saya.",
  ui_story_5001_50011102_19_dialog_content = "Pembicaraan besar, datang dari seorang gadis kecil.",
  ui_story_5001_50011102_20_dialog_content = "Apakah Anda mengatakan bahwa Eclipsites ini bukan sekutu Anda?",
  ui_story_5001_50011102_21_dialog_content = "Siapa yang waras akan bersekutu dengan makhluk seperti mereka? Apakah Anda tidak mengerti apa artinya \"menyerah\"?",
  ui_story_5001_50011102_22_dialog_content = "Jadi Anda menggunakan kekerasan untuk membuat mereka patuh?",
  ui_story_5001_50011102_23_dialog_content = "Siapa peduli? Ngomong-ngomong, kamu keberatan memberi tahu kami mengapa kamu menyeret Eve ke sini?",
  ui_story_5001_50011102_24_dialog_content = "Jika ini adalah ide lelucon Anda, saya sarankan Anda menghentikannya sekarang juga, dan tersesat.",
  ui_story_5001_50011102_25_dialog_content = "Saya mengambil Hawa sekarang, dan itu final.",
  ui_story_5001_50011102_26_dialog_content = "Anda tidak bisa.",
  ui_story_5001_50011102_27_dialog_content = "Saya tidak bertanya, Anda anak nakal!",
  ui_story_5001_50011102_28_dialog_content = "Dia ... saya <color=#FFB400>saudari</color>!!",
  ui_story_5001_50011102_29_dialog_content = "???",
  ui_story_5001_50011102_30_dialog_content = "???",
  ui_story_5001_50011102_31_dialog_content = "Keluarga mereka... cukup besar.",
  ui_story_5001_50011102_32_dialog_content = "Sinsa...?",
  ui_story_5001_50011102_33_dialog_content = "Untuk apa kau menatapku? Aku bersumpah aku tidak mengenalnya!",
  ui_story_5001_50011102_34_dialog_content = "Apakah ini \"Hari Penculikan Sedunia\" atau semacamnya? Kenapa semua orang mencoba kabur dengan adikku?!",
  ui_story_5001_50011102_35_dialog_content = "Siapa namamu, nak?",
  ui_story_5001_50011102_36_dialog_content = "Anda bisa memanggil saya...",
  ui_story_5001_50011102_37_dialog_content = "<color=#FFB400>Fajar</color>.",
  ui_story_5001_50011201_1_dialog_content = "Anda bisa memanggil saya... <color=#FFB400>Fajar</color>.",
  ui_story_5001_50011201_2_dialog_content = "Maaf nak, tapi aku tidak ingat memiliki saudara perempuan dengan nama itu.",
  ui_story_5001_50011201_3_dialog_content = "Ugh, kita tidak akan kemana-mana seperti ini. Biarkan aku mencoba.",
  ui_story_5001_50011201_4_dialog_content = "Dawn, jika Anda saudara perempuan Hawa, apakah Anda tahu bahwa Hawa juga memiliki kakak laki-laki?",
  ui_story_5001_50011201_5_dialog_content = "Aku tahu.",
  ui_story_5001_50011201_6_dialog_content = "Jadi dia benar-benar punya kakak laki-laki...?",
  ui_story_5001_50011201_7_dialog_content = "Payah.",
  ui_story_5001_50011201_8_dialog_content = "Lalu... Apa kau tahu namanya juga?",
  ui_story_5001_50011201_9_dialog_content = "Aku lupa.",
  ui_story_5001_50011201_10_dialog_content = "Kenapa, kau kecil...!",
  ui_story_5001_50011201_11_dialog_content = "Biarkan aku menjatuhkan beberapa sopan santun padanya, bos! Lalu kita bisa mengambil Eve dan menyebutnya sehari, eh?",
  ui_story_5001_50011201_12_dialog_content = "Erm... Jadi, dalam kelompok orang ini, salah satunya adalah saudara laki-laki Hawa. Apakah Anda tahu siapa itu?",
  ui_story_5001_50011201_13_dialog_content = "...",
  ui_story_5001_50011201_15_dialog_content = "Anda, di sana, turun di sini.",
  ui_story_5001_50011201_16_dialog_content = "Aku?",
  ui_story_5001_50011201_17_dialog_content = "Turun.",
  ui_story_5001_50011201_18_option_content = "Baiklah, aku jongkok.",
  ui_story_5001_50011201_19_dialog_content = "Ada apa?",
  ui_story_5001_50011201_20_option_content = "... Untuk apa itu?",
  ui_story_5001_50011201_22_dialog_content = "Hai! Kenapa kau merobek pakaianku?!",
  ui_story_5001_50011201_23_dialog_content = "Lengan... Dagu... Mata...",
  ui_story_5001_50011201_24_dialog_content = "H-Hei, jangan menyentuh!!!",
  ui_story_5001_50011201_25_dialog_content = "Dan aroma aneh ini... Itu bukan Lumina.",
  ui_story_5001_50011201_26_dialog_content = "Tunggu... Lihat, teman-teman! Mata fajar, mereka...",
  ui_story_5001_50011201_A1_dialog_content = "Saya juga memperhatikannya. Dia tidak bisa melihat apa-apa.",
  ui_story_5001_50011201_27_dialog_content = "Selesai.",
  ui_story_5001_50011201_28_dialog_content = "Hah?",
  ui_story_5001_50011201_29_dialog_content = "Kamu kakak Eve.",
  ui_story_5001_50011201_30_dialog_content = "Ada satu orang lagi, Fajar.",
  ui_story_5001_50011201_31_dialog_content = "Itu bukan dia.",
  ui_story_5001_50011201_32_dialog_content = "Hah?",
  ui_story_5001_50011201_33_dialog_content = "Eve berkata bahwa kakaknya juga lembut, baik, dan tampan.",
  ui_story_5001_50011201_34_dialog_content = "Maksudnya?! Itu bos kami, tidak diragukan lagi!",
  ui_story_5001_50011201_35_dialog_content = "Lalu... Apakah itu berarti aku bisa membawa Hawa sekarang?",
  ui_story_5001_50011201_36_dialog_content = "Itu tak akan ada gunanya.",
  ui_story_5001_50011201_37_dialog_content = "Kenapa?",
  ui_story_5001_50011201_38_dialog_content = "Ini belum waktunya, belum. Aku berjanji padanya... Ini hampir berakhir.",
  ui_story_5001_50011201_39_dialog_content = "Hah???",
  ui_story_5001_50011201_40_dialog_content = "Anda...! Apa yang sedang kamu lakukan?!",
  ui_story_5001_50011201_41_dialog_content = "...",
  ui_story_5001_50011201_42_dialog_content = "Hawa, aku di sini sekarang! Saya minta maaf...",
  ui_story_5001_50011201_43_dialog_content = "...",
  ui_story_5001_50011201_44_dialog_content = "Ayo kita pulang...",
  ui_story_5001_50011201_45_dialog_content = "Heeeeeee!",
  ui_story_5001_50011201_46_dialog_content = "Kamu gila?!",
  ui_story_5001_50011201_47_dialog_content = "Minggir.",
  ui_story_5001_50011201_48_dialog_content = "Malam! Pegang lenganku!",
  ui_story_5001_50011201_49_dialog_content = "Ini belum waktunya! Hanya sedikit lebih lama!",
  ui_story_5001_50011201_50_dialog_content = "Unggh... Ugh...",
  ui_story_5001_50011201_51_dialog_content = "Malam?!",
  ui_story_5001_50011201_52_dialog_content = "Ada apa dengan dia? Apakah dia sakit?",
  ui_story_5001_50011201_53_dialog_content = "Dia sudah terlalu lama berada di luar ruang isolasi! Ayo, Eve, kita harus cepat kembali!",
  ui_story_5001_50011201_54_dialog_content = "Bunga-bunga...",
  ui_story_5001_50011201_55_dialog_content = "Apa?",
  ui_story_5001_50011201_56_dialog_content = "!!",
  ui_story_5001_50011201_57_dialog_content = "<color=#e8d9bb>Fajar membungkuk, dengan lembut membelai bunga-bunga putih yang tumbuh dari rerumputan.</color>",
  ui_story_5001_50011201_58_dialog_content = "Bunga-bunga ini...",
  ui_story_5001_50011201_59_dialog_content = "Apa yang kalian berdua bicarakan?",
  ui_story_5001_50011201_60_dialog_content = "Anda menginjak bunga saya!!",
  ui_story_5001_50011201_61_dialog_content = "!!!",
  ui_story_5001_50011202_1_dialog_content = "*Batuk-batuk*",
  ui_story_5001_50011202_2_dialog_content = "Sinsa!",
  ui_story_5001_50011202_3_dialog_content = "Jangan khawatir, aku tidak akan membunuhnya.",
  ui_story_5001_50011202_4_dialog_content = "Kakak…",
  ui_story_5001_50011202_5_dialog_content = "Aku di sini, Hawa. Regina, ambilkan aku air!",
  ui_story_5001_50011202_6_dialog_content = "Datang, bos!",
  ui_story_5001_50011202_7_dialog_content = "Ini Hawa, minum ini. Anda akan merasa lebih baik, saya janji.",
  ui_story_5001_50011202_8_dialog_content = "Kakak... Bunga...",
  ui_story_5001_50011202_9_dialog_content = "Dia dalam kondisi yang sangat buruk, Sinsa. Aku tidak yakin kita akan kembali ke Tail Street tepat waktu...",
  ui_story_5001_50011202_10_dialog_content = "Bagaimana perbaikanmu, Soroz? Udah bisa pindah belum?",
  ui_story_5001_50011202_11_dialog_content = "Kemajuan telah lambat. Saya masih memiliki banyak bagian yang perlu diperbaiki... Saya minta maaf.",
  ui_story_5001_50011202_12_dialog_content = "Aduh…!",
  ui_story_5001_50011202_13_dialog_content = "Malam?!",
  ui_story_5001_50011202_14_dialog_content = "Fajar! Apa yang telah kamu lakukan padanya?!",
  ui_story_5001_50011202_15_dialog_content = "Tidak ada sama sekali. Saya hanya membawanya ke sini, di mana kami berjanji untuk bertemu.",
  ui_story_5001_50011202_16_dialog_content = "Kami berjuang sangat keras untuk menepati janji kami dan berhasil sampai di sini ... Tapi kalian ikut campur, dan tepat pada saat yang paling penting ...",
  ui_story_5001_50011202_17_dialog_content = "Janji sialan apa? Dia sekarat karenamu!",
  ui_story_5001_50011202_18_dialog_content = "Saya mengerti. Lagipula, tidak ada yang benar-benar mengerti rasa sakitnya.",
  ui_story_5001_50011202_19_dialog_content = "Rasa sakit? Saya akan menunjukkan rasa sakit!",
  ui_story_5001_50011202_20_dialog_content = "...",
  ui_story_5001_50011202_21_dialog_content = "Eve?",
  ui_story_5001_50011202_22_dialog_content = "...",
  ui_story_5001_50011202_23_dialog_content = "Oh tidak, dia pingsan!",
  ui_story_5001_50011301_1_dialog_content = "Oh tidak, dia pingsan!",
  ui_story_5001_50011301_2_dialog_content = "Dapatkan med-kit! Buru-buru!",
  ui_story_5001_50011301_3_dialog_content = "Medkit kembali ke Lepidoz, Sinsa...",
  ui_story_5001_50011301_4_dialog_content = "Biarkan aku melihatnya! Bergerak!",
  ui_story_5001_50011301_5_dialog_content = "Malam? Ini aku, Fajar. Bisakah kamu mendengarku?",
  ui_story_5001_50011301_6_dialog_content = "Tangannya sedingin es! Aliran Gelap semakin padat... Dia mulai berputar!",
  ui_story_5001_50011301_7_dialog_content = "Apa maksudmu, \"dia mulai berubah\"?",
  ui_story_5001_50011301_8_dialog_content = "Aku tahu apa yang dia maksud. Kita harus menenangkan Hawa. Kembali, kalian semua!",
  ui_story_5001_50011301_9_dialog_content = "Kakak ada di sini, Hawa. Jangan khawatir, kita aman di sini. Tidak ada Eclipsites buruk di sini yang bisa menyakitimu...",
  ui_story_5001_50011301_10_dialog_content = "!!",
  ui_story_5001_50011301_11_dialog_content = "Hah?! <color=#FFB400>Arus listrik</color>?",
  ui_story_5001_50011301_12_dialog_content = "Jangan sentuh dia! Dia... Urgh!!!",
  ui_story_5001_50011301_13_dialog_content = "Biarkan kami membantu Anda, Sinsa!!",
  ui_story_5001_50011301_14_dialog_content = "Tidak apa-apa, Hawa! Aku bersamamu, aku tahu seberapa besar penderitaanmu saat ini...",
  ui_story_5001_50011301_15_dialog_content = "!!",
  ui_story_5001_50011301_16_dialog_content = "!",
  ui_story_5001_50011301_17_dialog_content = "Hawa... Ini untukmu!",
  ui_story_5001_50011301_18_dialog_content = "Aku menyuruhmu untuk tetap kembali, Dawn! Hawa... Hrrgh! Kekuatannya, itu...",
  ui_story_5001_50011301_19_dialog_content = "Ambil bunganya, Hawa! Ingat... Ingat janji kita...",
  ui_story_5001_50011301_20_dialog_content = "Ugh...",
  ui_story_5001_50011301_21_dialog_content = "...",
  ui_story_5001_50011301_22_dialog_content = "Dia... Dia tenang? Itu berhasil?",
  ui_story_5001_50011301_23_dialog_content = "Sinsa, tubuhmu...",
  ui_story_5001_50011301_24_dialog_content = "Tidak apa-apa, jangan khawatir tentang itu. Eve... Dia tidak sadar apa yang dia lakukan.",
  ui_story_5001_50011301_25_dialog_content = "Jika Eve terus kehilangan kendali, apakah Anda berencana untuk memeluknya seperti ini setiap saat?",
  ui_story_5001_50011301_26_dialog_content = "Ya.",
  ui_story_5001_50011301_27_dialog_content = "Aku tidak pernah melepaskannya, setelah bertahun-tahun, dan tidak akan pernah. Tidak hari ini... Tidak pernah.",
  ui_story_5001_50011301_28_dialog_content = "...",
  ui_story_5001_50011301_29_dialog_content = "PlayerName…",
  ui_story_5001_50011301_30_dialog_content = "Eve?",
  ui_story_5001_50011301_31_dialog_content = "Kakak... Fajar...",
  ui_story_5001_50011301_32_dialog_content = "Mereka juga di sini, Hawa. Bagaimana perasaanmu? Baru saja...",
  ui_story_5001_50011301_33_dialog_content = "Maaf... Aku menyakiti seseorang lagi, bukan?",
  ui_story_5001_50011301_34_dialog_content = "Itu bukan salahmu, Hawa. Biarkan saya membantu Anda.",
  ui_story_5001_50011301_35_dialog_content = "Semua orang selalu mengatakan itu padaku.",
  ui_story_5001_50011301_36_dialog_content = "Dia juga mengatakan itu padaku...",
  ui_story_5001_50011301_37_dialog_content = "Ceritakan apa yang terjadi, Hawa.",
  ui_story_5001_50011301_38_dialog_content = "Sakit... di sekujur tubuhku. Sesuatu... mengalir di nadiku... panas... dan juga dingin.",
  ui_story_5001_50011301_39_dialog_content = "<anim type=Shake>Anda tidak layak.</anim>",
  ui_story_5001_50011301_40_dialog_content = "<anim type=Shake>Ini semua salahmu!</anim>",
  ui_story_5001_50011301_41_dialog_content = "<anim type=Shake>Aku mohon, tolong hentikan!</anim>",
  ui_story_5001_50011301_42_dialog_content = "<anim type=Shake>Menghancurkan! Menghancurkan!! Dimana wanita itu?!?</anim>",
  ui_story_5001_50011301_43_dialog_content = "PlayerName!",
  ui_story_5001_50011301_44_dialog_content = "Malam?!",
  ui_story_5001_50011301_45_dialog_content = "Eve…",
  ui_story_5001_50011301_46_dialog_content = "Apakah Anda mendengar sesuatu, PlayerName?",
  ui_story_5001_50011301_47_dialog_content = "Ya. Itu Eve... Dia berteriak minta tolong.",
  ui_story_5001_50011301_48_dialog_content = "Membantu?",
  ui_story_5001_50011301_49_dialog_content = "Dia terjebak jauh di dalam pikirannya sendiri, Sinsa! Tapi aku bisa membantunya... Aku bisa membangunkannya!",
  ui_story_5001_50011301_50_dialog_content = "Maksudmu?",
  ui_story_5001_50011301_51_dialog_content = "Kamu... Ugh, sebut saja itu intuisiku sendiri. Apakah itu berhasil untuk Anda?",
  ui_story_5001_50011301_52_dialog_content = "Baik. Aku akan mempercayaimu, sekali ini saja. Tapi sebelum itu, katakan padaku apa sebenarnya yang kau rencanakan untuk dilakukan pada adikku.",
  ui_story_5001_50011301_53_dialog_content = "Aku melihat banyak Hawa barusan... Aku harus menemukan cara untuk menyelamatkan yang asli!",
  ui_story_5001_50011301_54_dialog_content = "Ada orang lain di dalam hati nuraninya juga! Tidak... Sebaliknya, mereka adalah sisa-sisa korup dari orang lain!",
  ui_story_5001_50011301_55_dialog_content = "Apakah Anda mengerti apa yang saya katakan?",
  ui_story_5001_50011301_56_dialog_content = "Baiklah...",
  ui_story_5001_50011301_57_dialog_content = "Hah? B-benarkah?",
  ui_story_5001_50011301_58_dialog_content = "Ya. Masa lalunya dekat dengan apa yang baru saja Anda gambarkan... Setidaknya, saya percaya bahwa Anda benar-benar dapat merasakan sesuatu pada orang.",
  ui_story_5001_50011301_59_dialog_content = "<color=#FFB400>Saya akan mencoba dan menemukannya lagi</color>. Ini tidak mudah, dan saya tidak tahu apakah itu akan berhasil... Tapi saya harus mencoba.",
  ui_story_5001_50011301_60_dialog_content = "Tunggu, kita perlu melakukan ini di tempat lain!",
  ui_story_5001_50011301_61_dialog_content = "Kami tidak punya waktu untuk disia-siakan! Kita tidak bisa membiarkan Hawa berubah menjadi itu lagi...",
  ui_story_5001_50011301_62_dialog_content = "Badai mendekat.",
  ui_story_5001_50011301_63_dialog_content = "Apa?",
  ui_story_5001_50011301_64_dialog_content = "Badai sedang mendekati kita! Sesuatu membuatnya tidak seimbang, dan itu berkontraksi!",
  ui_story_5001_50011301_65_dialog_content = "Apakah kita mengganggu badai entah bagaimana, ketika kita melewatinya? Berapa banyak waktu yang tersisa?",
  ui_story_5001_50011301_66_dialog_content = "Entahlah, udara berubah terlalu cepat untuk diceritakan. Kita mungkin punya waktu satu jam... atau kurang.",
  ui_story_5001_50011301_67_dialog_content = "Bagaimanapun, kita harus pindah ke tempat yang lebih aman!",
  ui_story_5001_50011301_68_dialog_content = "S-Sangat dingin! Suhu mulai turun!",
  ui_story_5001_50011301_69_dialog_content = "Kita harus aman di sini untuk saat ini, kurasa.",
  ui_story_5001_50011301_70_dialog_content = "Mata badai menyusut cukup cepat untuk melihat dengan mata kita. Bagaimana Soroz?",
  ui_story_5001_50011301_71_dialog_content = "Jangan khawatir, Soroz bisa mengatasinya. Saya yakin Colossus kita telah menemukan perlindungan dari badai.",
  ui_story_5001_50011301_72_dialog_content = "Dan Hawa? Bagaimana dengannya?",
  ui_story_5001_50011301_73_dialog_content = "Ini tidak terlihat bagus. Dia masih tidak sadarkan diri, dan pikirannya dalam keadaan kacau.",
  ui_story_5001_50011301_74_dialog_content = "Di sini, buatlah ruang untuk Hawa.",
  ui_story_5001_50011301_75_dialog_content = "Jangan terlalu dekat ke tepi, semuanya. Angin semakin kencang.",
  ui_story_5001_50011301_76_dialog_content = "Maaf, Sinsa, karena salah menilaimu sebelumnya.",
  ui_story_5001_50011301_77_dialog_content = "Jika permintaan maafmu adalah bagian dari rencanamu untuk membangunkan Eve, aku akan dengan senang hati menerimanya.",
  ui_story_5001_50011301_78_dialog_content = "Aku akan menyelamatkannya, Sinsa. Saya berjanji.",
  ui_story_5001_50011301_79_dialog_content = "Bos! Kita semua siap di sini!",
  ui_story_5001_50011301_80_dialog_content = "Ya, kami juga baik-baik saja di sini. Lanjutkan.",
  ui_story_5001_50011301_81_dialog_content = "Wah, apa itu? Ini sangat hangat!",
  ui_story_5001_50011301_84_dialog_content = "kekuatan Regina. Dia bisa sangat berguna, sesekali.",
  ui_story_5001_50011301_85_dialog_content = "Aku mendengarnya, bos! Anda mengatakan saya tidak membantu Anda sepanjang waktu?",
  ui_story_5001_50011301_86_dialog_content = "Apakah kamu masih kedinginan, Hawa?",
  ui_story_5001_50011301_87_dialog_content = "...",
  ui_story_5001_50011301_88_dialog_content = "Kamu suka bunga ini, kan, Hawa? Meski tidak nyata...",
  ui_story_5001_50011301_89_dialog_content = "...",
  ui_story_5001_50011301_91_dialog_content = "Bahkan jika kita menjangkau ... ke sepetak langit biru di atas kita ...",
  ui_story_5001_50011301_92_dialog_content = "Sebesar apapun kita mendambakannya...",
  ui_story_5001_50011301_93_dialog_content = "Kami tidak punya cara untuk sampai di sana. Kami terjebak di sini...",
  ui_story_5001_50011301_94_dialog_content = "Tapi setidaknya Anda bisa melihat cahaya di atas, bukan?",
  ui_story_5001_50011301_95_dialog_content = "Kembali ketika saya masih bisa melihat, saya bertemu banyak orang dalam kesulitan Hawa ... Tapi tidak satupun dari mereka yang pernah bangun.",
  ui_story_5001_50011301_96_dialog_content = "Hati mereka terkunci dalam perjuangan terus-menerus melawan kegelapan... Mereka yang tidak memiliki tekad yang kuat akhirnya termakan oleh kegelapan itu.",
  ui_story_5001_50011301_97_dialog_content = "Mereka menjadi korban... atas nama eksperimen.",
  ui_story_5001_50011301_98_dialog_content = "Tapi Hawa masih berjuang... Dia belum menyerah.",
  ui_story_5001_50011301_99_dialog_content = "...",
  ui_story_5001_50011301_100_dialog_content = "PlayerName.",
  ui_story_5001_50011301_101_dialog_content = "Ya, Sinsa?",
  ui_story_5001_50011301_102_dialog_content = "Anda satu-satunya harapan yang saya miliki untuk membawa cahaya kembali ke dalam hidup saya lagi.",
  ui_story_5001_50011301_103_dialog_content = "Jadi tolong, PlayerName...",
  ui_story_5001_50011301_104_dialog_content = "Akan kuceritakan semuanya... semua yang kutahu tentang masa lalu Eve.",
  ui_story_5001_50011301_A1_dialog_content = "Kau satu-satunya yang bisa menghubunginya sekarang, jadi tolong... Gunakan kekuatan Caelestitemu dan temukan dia. Temukan dia dan bawa dia kembali padaku.",
  ui_story_5001_50011301_105_dialog_content = "Aku khawatir jiwa Hawa sudah menjadi seperti laut tak terukur, Caelestit. Jika Anda tidak mempersiapkan diri dengan baik...",
  ui_story_5001_50011301_106_dialog_content = "Anda juga akan tersesat di kedalamannya.",
  ui_story_5001_50020100_1_dialog_content = "Aku di sini!",
  ui_story_5001_50020100_2_dialog_content = "Bisakah kamu mendengarku, Hawa?",
  ui_story_5001_50020100_3_dialog_content = "Beri saya tanda jika Anda ada di sekitar. Saya bisa bantu anda! Kita...",
  ui_story_5001_50020100_4_dialog_content = "Wah, itu perasaan yang intens.",
  ui_story_5001_50020100_5_dialog_content = "Mungkin kamu takut atau bahkan sangat marah, Eve, tapi tidak apa-apa!",
  ui_story_5001_50020100_6_dialog_content = "Aku di sini Untukmu. Kamu tidak perlu menahannya lagi, Eve.",
  ui_story_5001_50020100_7_dialog_content = "...",
  ui_story_5001_50020100_8_dialog_content = "Anda tidak perlu berjuang sendirian lagi. Aku disini.",
  ui_story_5001_50020100_9_dialog_content = "Mari kita hadapi emosi dan kenangan ini bersama-sama.",
  ui_story_5001_50020100_10_dialog_content = "...",
  ui_story_5001_50020100_11_option_content = "*Menjelajahi kesadaran Hawa*",
  ui_story_5002_50020101_1_dialog_content = "<color=#e8d9bb>Desa Ngarai Mata Merah, Bertahun-tahun Yang Lalu</color>",
  ui_story_5002_50020101_2_dialog_content = "Hahaha!",
  ui_story_5002_50020101_3_dialog_content = "Lewat sini, saudara!",
  ui_story_5002_50020101_4_dialog_content = "Anda terlalu lambat! Sini, pegang tanganku!",
  ui_story_5002_50020101_5_dialog_content = "Hah? Anda ingin kembali sudah?",
  ui_story_5002_50020101_6_dialog_content = "Anda selalu terlalu khawatir, saudara ...",
  ui_story_5002_50020101_7_dialog_content = "Lihat, saudara! Para pedagang kembali!",
  ui_story_5002_50020101_8_dialog_content = "Saya ingin melihat apakah mereka memiliki sesuatu yang baru!",
  ui_story_5002_50020101_9_dialog_content = "Tidakkah kamu ingin tahu seperti apa dunia luar itu, saudara?",
  ui_story_5002_50020101_10_dialog_content = "Kamu yang terhebat, kakak! Tidak ada yang terlalu berbahaya untukmu!",
  ui_story_5002_50020101_11_dialog_content = "Aku akan kembali sebelum matahari terbenam, oke? Saya berjanji!",
  ui_story_5002_50020101_12_dialog_content = "Hah!",
  ui_story_5002_50020101_13_dialog_content = "Jadi ini danaunya ya? Hmm... Jadi seperti itu!",
  ui_story_5002_50020101_14_dialog_content = "Oh tidak, jam berapa sekarang? Jika aku tidak cepat kembali, kakakku akan sangat marah hingga dia akan membusungkan dada seperti katak...",
  ui_story_5002_50020101_15_dialog_content = "Uh... Apakah ini arah timur?",
  ui_story_5002_50020101_16_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5002_50020101_17_dialog_content = "Suara apa itu?",
  ui_story_5002_50020101_18_dialog_content = "Eve…",
  ui_story_5002_50020101_19_dialog_content = "Malam!! Kamu ada di mana?!",
  ui_story_5002_50020101_20_dialog_content = "B... Kakak...",
  ui_story_5002_50020101_21_dialog_content = "Aku…",
  ui_story_5002_50020101_22_dialog_content = "Kotor... Tanganku kotor...",
  ui_story_5002_50020101_23_dialog_content = "Mereka berlumuran darah... Saudaraku, aku tidak bisa mencucinya... Mereka kotor...",
  ui_story_5002_50020101_24_dialog_content = "Mama? Ayah? Bisakah aku... pulang sekarang?",
  ui_story_5002_50020101_25_dialog_content = "<anim type=Shake>Mereka disini. Monster... Mereka ada di desa sekarang.</anim>",
  ui_story_5002_50020101_26_dialog_content = "<anim type=Shake>Orang-orang itu pergi menuju kematian mereka... Tapi bagaimana dengan saudaraku? Dimana dia?</anim>",
  ui_story_5002_50020101_27_dialog_content = "<anim type=Shake>Oh, dia tepat di depanku sambil berpegangan tangan...</anim>",
  ui_story_5002_50020101_28_dialog_content = "<anim type=Shake>Tetap hidup... Berjalan di atas mayat semua orang untuk melarikan diri, jika harus... Tapi tetaplah hidup.</anim>",
  ui_story_5002_50020101_29_dialog_content = "Kakak…",
  ui_story_5002_50020101_30_dialog_content = "Ada apa, Hawa?",
  ui_story_5002_50020101_31_dialog_content = "Begitu banyak bunga...",
  ui_story_5002_50020101_32_dialog_content = "Ya... Cantik, bukan?",
  ui_story_5002_50020101_33_dialog_content = "Jika ini mimpi... Aku tidak pernah ingin bangun.",
  ui_story_5002_50020101_34_dialog_content = "Semua orang masih hidup dalam mimpiku... Ibu, ayah, dan penduduk desa lainnya...",
  ui_story_5002_50020101_35_dialog_content = "Ya, semua orang masih di sini. Mereka tidak pernah datang, jadi semua orang masih di sini...",
  ui_story_5002_50020101_36_dialog_content = "Itu benar... Semua orang masih di sini, lihat...",
  ui_story_5002_50020101_37_dialog_content = "<anim type=Shake>Berbohong. Kebohongan kotor. Semuanya hancur berkeping-keping ...</anim>",
  ui_story_5002_50020101_38_dialog_content = "<anim type=Shake>Kakak... Ibu... Seseorang, tolong... Selamatkan aku...</anim>",
  ui_story_5002_50020102_1_dialog_content = "<anim type=Shake>Tolong, aku... aku tidak ingin menghilang...</anim>",
  ui_story_5002_50020102_2_dialog_content = "<anim type=Shake>Jangan menjauh dariku! Jangan tinggalkan aku! Kita satu tubuh...</anim>",
  ui_story_5002_50020102_3_dialog_content = "<anim type=Shake>Cerita belum berakhir, kita belum sampai ke halaman terakhir... Buku... masih dibuka...</anim>",
  ui_story_5002_50020102_4_dialog_content = "Tuan Pendongeng! Saya kembali!",
  ui_story_5002_50020102_5_dialog_content = "Mengapa, jika bukan Hawa! Ya ampun, kamu sudah dewasa, bukan?",
  ui_story_5002_50020102_6_dialog_content = "Aku membawakanmu batu yang sangat aneh! Melihat? Itu terlihat seperti katak!",
  ui_story_5002_50020102_7_dialog_content = "Ha ha ha ha! Aneh, memang! Saya yakin ini akan menjadi sumber pengetahuan yang luar biasa bagi kita semua di Illumina. Terima kasih, Hawa!",
  ui_story_5002_50020102_8_dialog_content = "Heee! Katakan, tuan, tahukah Anda bahwa saya menyelesaikan buku bergambar yang Anda berikan kepada saya terakhir kali!",
  ui_story_5002_50020102_9_dialog_content = "Apakah begitu? Lalu untuk berterima kasih atas batu berharga ini, mengapa saya tidak memberi Anda buku baru? Sekarang, mari kita lihat apa yang saya miliki di sini ...",
  ui_story_5002_50020102_10_dialog_content = "Terima kasih, tuan! Tapi ada satu hal yang saya tidak bisa mengerti ...",
  ui_story_5002_50020102_11_dialog_content = "Ada sesuatu yang disebut \"salju\" di buku itu... Aku menonton sepanjang musim dingin, tapi aku tidak pernah melihatnya! Apakah itu benar-benar ada?",
  ui_story_5002_50020102_12_dialog_content = "Anak bodoh, Ngarai Mata Merah terletak di... Oh! Maafkan aku, Hawa! Aku tidak bermaksud terdengar begitu singkat.",
  ui_story_5002_50020102_13_dialog_content = "Ahem, Ngarai Mata Merah terlalu panas, Eve. Salju mencair di langit sebelum sempat mencapai tanah.",
  ui_story_5002_50020102_14_dialog_content = "Lalu... Apakah itu berubah menjadi hujan?",
  ui_story_5002_50020102_15_dialog_content = "Anda sangat cerdik, Hawa.",
  ui_story_5002_50020102_16_dialog_content = "Lalu... Apakah tempat yang sangat dingin akan memiliki salju?",
  ui_story_5002_50020102_17_dialog_content = "Ya! Dan sebenarnya ada tempat seperti itu! Ini disebut \"Northland.\"",
  ui_story_5002_50020102_18_dialog_content = "tanah utara... tanah utara...",
  ui_story_5002_50020102_19_dialog_content = "Coba bayangkan, Hawa: tempat di mana semuanya tertutup salju putih paling murni...",
  ui_story_5002_50020102_20_dialog_content = "Ada sebuah danau di sana juga! Halus seperti kaca, memantulkan cahaya aurora yang bersinar di atas. Tempat dimana langit dan bumi menyatu...",
  ui_story_5002_50020102_21_dialog_content = "Wow... Saat aku besar nanti, aku ingin pergi melihat Northland! Tapi berapa lama itu akan...",
  ui_story_5002_50020102_22_dialog_content = "Hahaha, jangan terburu-buru, Hawa.",
  ui_story_5002_50020102_23_dialog_content = "Aku baru ingat, ada sebuah danau di sebelah timur Ngarai Mata Merah, tidak jauh dari tempat kami berada sekarang. Tapi saya yakin itu tidak seperti danau di Northland!",
  ui_story_5002_50020102_24_dialog_content = "Hari itu... Itu adalah hari dimana para pedagang pergi setelah mereka selesai berdagang.",
  ui_story_5002_50020102_25_dialog_content = "Saya ingin pergi melihat danau yang dia ceritakan kepada saya. Saya ingin melihat dunia yang lebih besar, bahkan hanya sebagian kecil saja.",
  ui_story_5002_50020102_26_dialog_content = "Jadi saya menyelinap ke salah satu gerobak pedagang dan meninggalkan desa tanpa memberi tahu saudara saya ...",
  ui_story_5002_50020102_27_dialog_content = "Jadi danau benar-benar terlihat seperti cermin besar!",
  ui_story_5002_50020102_28_dialog_content = "Hah? Bayangan apa yang ada di sebelahku?",
  ui_story_5002_50020102_29_dialog_content = "Hah?",
  ui_story_5002_50020102_30_dialog_content = "Hei!",
  ui_story_5002_50020102_31_dialog_content = "Aaaa!!",
  ui_story_5002_50020102_32_dialog_content = "Hei tunggu...!",
  ui_story_5002_50020102_33_dialog_content = "Urgh, t-tolong... Jangan dikejar!",
  ui_story_5002_50020102_34_dialog_content = "Huff... Aku mencoba mengatakan... kakimu... terluka.",
  ui_story_5002_50020102_35_dialog_content = "hrg? Uaagh... Sakit!",
  ui_story_5002_50020102_36_dialog_content = "Anda ... Anda mengejar ... untuk ini? Untuk saya?",
  ui_story_5002_50020102_37_dialog_content = "Ambil ini. Ibuku menyuruhku membawa obat ini kemanapun aku pergi. Hanya menggosok beberapa di atasnya, dan itu berhenti sakit! Seperti sihir!",
  ui_story_5002_50020102_38_dialog_content = "Anda... Orang baik?",
  ui_story_5002_50020102_39_dialog_content = "Urgh...B-Buruk! Ini buruk! Anda, pergi dari sini! Buru-buru!",
  ui_story_5002_50020102_40_dialog_content = "<size=50>Lari!</size>",
  ui_story_5002_50020102_41_dialog_content = "Kemudian...",
  ui_story_5002_50020102_42_dialog_content = "Bayangan yang tak terhitung jumlahnya muncul di sekitarku.",
  ui_story_5002_50020102_43_dialog_content = "Mereka menemukan saya.",
  ui_story_5002_50020102_44_dialog_content = "Ketika saya sadar, yang saya lihat hanyalah mayat mereka di sekitar saya ...",
  ui_story_5002_50020102_45_dialog_content = "Aku telah membangkitkan semacam kekuatan, tapi... Aku takut.",
  ui_story_5002_50020102_46_dialog_content = "Saya berlari untuk hidup saya kembali ke desa.",
  ui_story_5002_50020102_47_dialog_content = "Saya tidak melakukan itu, kan? Ini tidak mungkin benar... Pasti ada kesalahan...",
  ui_story_5002_50020102_48_dialog_content = "aku bukan monster...",
  ui_story_5002_50020102_49_dialog_content = "Aku bukan monster... Benar?",
  ui_story_5002_50020102_50_dialog_content = "Saya harus membersihkan diri. Saya tidak ingin menakut-nakuti ibu atau ayah, atau saudara ...",
  ui_story_5002_50020102_51_dialog_content = "Tapi aku tidak bisa. Darah menempel di pakaianku dan menodai kulitku... Darah itu merembes ke dalam diriku, sampai ke tulang-tulangku...",
  ui_story_5002_50020102_52_dialog_content = "Pulang adalah sebuah kesalahan. Sebuah kesalahan yang akan datang dengan harga yang mengerikan...",
  ui_story_5002_50020102_53_dialog_content = "Saya tidak tahu, tetapi lebih banyak lagi Eclipsites telah mengikuti saya kembali ke desa ...",
  ui_story_5002_50020102_54_dialog_content = "Dan... Mereka menghancurkan segalanya.",
  ui_story_5002_50020102_55_dialog_content = "<size=45>Saudara laki-laki!</size>",
  ui_story_5002_50020102_56_dialog_content = "Tanganmu!",
  ui_story_5002_50020102_57_dialog_content = "maafkan aku... maafkan aku...",
  ui_story_5002_50020102_58_dialog_content = "Dari mana semua Eclipsites ini berasal? Mengapa mereka menyerang desa?",
  ui_story_5002_50020102_59_dialog_content = "Dan badai itu... Apa aku yang membuat ini terjadi? Aku hanya ingin melindungi semua orang, dan mengusir monster itu...",
  ui_story_5002_50020102_60_dialog_content = "Hawa... Ini bukan salahmu... Ini semua hanya... bencana alam...",
  ui_story_5002_50020102_61_dialog_content = "Betul sekali. Langit dan gunung terbangun, dan dari sanalah Eclipsites berasal. Itu saja...",
  ui_story_5002_50020102_62_dialog_content = "Ayo, Hawa. Aku akan membawamu.",
  ui_story_5002_50020102_63_dialog_content = "Kita harus meninggalkan Red-Eye Gorge... sebelum badai benar-benar mengelilingi kita.",
  ui_story_5002_50020201_1_dialog_content = "Saya pernah melihat penyakit ini sebelumnya.",
  ui_story_5002_50020201_2_dialog_content = "Jangan khawatir, serahkan saja dia padaku dan aku akan membuatnya lebih baik.",
  ui_story_5002_50020201_3_dialog_content = "<color=#e8d9bb>Sepuluh Tahun Yang Lalu, Di Sebuah Kota Bawah Yang Tidak Diketahui</color>",
  ui_story_5002_50020201_4_dialog_content = "Apakah kamu Hawa?",
  ui_story_5002_50020201_5_dialog_content = "Halo...",
  ui_story_5002_50020201_6_dialog_content = "Anda dalam kondisi yang mengerikan. Anda seharusnya datang lebih cepat, Anda tahu.",
  ui_story_5002_50020201_7_dialog_content = "Kudengar saudaramu menawarkan Kunci Pas Rediesel untuk bergabung dengan Koalisi sebagai imbalan atas bantuan Illumina?",
  ui_story_5002_50020201_8_dialog_content = "Tidak pernah terpikir saya akan melihat hari dimana bandit-bandit itu akan bergantung pada orang lain untuk mendapatkan dukungan.",
  ui_story_5002_50020201_9_dialog_content = "Bagaimanapun, Anda dapat bersantai sekarang. Aku akan menjagamu dengan baik.",
  ui_story_5002_50020201_10_dialog_content = "Saya satu-satunya di seluruh Astra yang dapat membantu Anda sekarang.",
  ui_story_5002_50020201_11_dialog_content = "(Lantai... Ini sangat dingin.)",
  ui_story_5002_50020201_12_dialog_content = "Malam.",
  ui_story_5002_50020201_13_dialog_content = "Kita harus pindah lokasi.",
  ui_story_5002_50020201_14_dialog_content = "Transfer? Di mana?",
  ui_story_5002_50020201_15_dialog_content = "Undercity yang berbeda, di mana tidak ada yang akan mengganggu kita.",
  ui_story_5002_50020201_16_dialog_content = "Fasilitas di sana akan lebih baik, jadi saya bisa membantu Anda lebih banyak lagi.",
  ui_story_5002_50020201_17_dialog_content = "Begitu juga dengan yang lainnya.",
  ui_story_5002_50020201_18_dialog_content = "Kakak…",
  ui_story_5002_50020201_19_dialog_content = "Kakakku tidak akan bisa menemukanku...",
  ui_story_5002_50020201_20_dialog_content = "Aku akan memberinya petunjuk arah ke lokasi baru kita, Eve. Percayalah padaku.",
  ui_story_5002_50020201_21_dialog_content = "Kamu harus tetap kuat untuk kakakmu... Mengerti?",
  ui_story_5002_50020201_22_dialog_content = "...",
  ui_story_5002_50020201_23_dialog_content = "Ya.",
  ui_story_5002_50020201_24_dialog_content = "(Kabel... Jarum suntik... Pintu pelindung...)",
  ui_story_5002_50020201_25_dialog_content = "(Apakah saya... benar-benar menjadi lebih baik?)",
  ui_story_5002_50020201_26_dialog_content = "Tidak!!!!",
  ui_story_5002_50020201_27_dialog_content = "Malam! Dimana kamu, Hawa?!",
  ui_story_5002_50020201_28_dialog_content = "(Fajar!)",
  ui_story_5002_50020201_29_dialog_content = "(Aku... aku di sini...)",
  ui_story_5002_50020201_30_dialog_content = "Suaraku tidak pernah keluar dari tenggorokanku... Tidak peduli seberapa keras aku berteriak dalam hatiku, dia tidak akan pernah bisa mendengarku.",
  ui_story_5002_50020201_31_dialog_content = "Dan sudah lama sekali aku tidak berbicara.",
  ui_story_5002_50020201_32_dialog_content = "Alat, sedingin es, dipanaskan hingga suhu panas.",
  ui_story_5002_50020201_33_dialog_content = "Langit-langitnya runtuh, dan udara di sekitarku menjadi hitam...",
  ui_story_5002_50020201_34_dialog_content = "Saudara ... Apakah Anda di sana? Apa kau bisa... menemukanku?",
  ui_story_5002_50020201_35_dialog_content = "\"Rumah\" baruku... Hancur juga...",
  ui_story_5002_50020201_36_dialog_content = "Semua ini...",
  ui_story_5002_50020201_37_dialog_content = "<size=45><anim type=Shake>Apakah semua ini... salahku juga?!</anim></size>",
  ui_story_5002_50020201_38_dialog_content = "<anim type=Shake>Api yang berkobar ini... Apa aku yang menyalakannya? Tidak... aku tidak bisa! Ini rumah baruku! aku tidak akan pernah menyakiti mereka...</anim>",
  ui_story_5002_50020201_39_dialog_content = "<anim type=Shake>Tidak!! Ini tidak mungkin nyata!!!</anim>",
  ui_story_5002_50020202_1_dialog_content = "<anim type=Shake>Tidak! Aku tidak ingin menghilang! Masih banyak yang harus dihancurkan!!</anim>",
  ui_story_5002_50020202_2_dialog_content = "<anim type=Shake>Kamar itu, wanita itu... Jeritan menjengkelkan itu...</anim>",
  ui_story_5002_50020202_3_dialog_content = "<anim type=Shake>Dan... bunga itu. Saya ingat nama mereka! Aku ingat...</anim>",
  ui_story_5002_50020202_A1_dialog_content = "Aku... aku tidak pernah lupa...",
  ui_story_5002_50020202_4_dialog_content = "Saudara, orang ini mengatakan mereka dapat menyembuhkan saya.",
  ui_story_5002_50020202_5_dialog_content = "Tidak apa-apa, saudara! Saya akan menjadi seperti baru dalam waktu singkat!",
  ui_story_5002_50020202_6_dialog_content = "...",
  ui_story_5002_50020202_7_dialog_content = "Ada gadis lain di kamarku... Tapi sepertinya dia tidak ingin berteman.",
  ui_story_5002_50020202_8_dialog_content = "Dia sama denganku. \"Sabar\" lainnya.",
  ui_story_5002_50020202_9_dialog_content = "Suatu hari, di sudut ruangan... Aku menemukan kuncup bunga.",
  ui_story_5002_50020202_A2_dialog_content = "Itu sama dengan bunga yang kulihat di buku bergambar itu, bertahun-tahun yang lalu... Bunga fajar.",
  ui_story_5002_50020202_10_dialog_content = "Para dokter tidak mengizinkan kami memiliki sesuatu yang istimewa di kamar kami... Tapi aku ingin melindunginya, seperti kakakku dulu melindungiku.",
  ui_story_5002_50020202_11_dialog_content = "Aku juga ingin seperti itu. Saya ingin tumbuh dan bertahan hidup, dengan sepenuh hati.",
  ui_story_5002_50020202_12_dialog_content = "Dan mungkin, ketika akhirnya mekar... Mungkin aku juga akan sembuh...",
  ui_story_5002_50020202_13_dialog_content = "Aku mendengar jeritan kesakitan sepanjang waktu di sana, tapi akhirnya... Semuanya akan hening kembali.",
  ui_story_5002_50020202_14_dialog_content = "Apakah saya harus melalui rasa sakit seperti itu untuk menjadi lebih baik juga?",
  ui_story_5002_50020202_15_dialog_content = "Kakak... aku takut...",
  ui_story_5002_50020202_16_dialog_content = "Kemudian, gadis yang berbagi kamar dengan saya menemukan rahasia saya: bunga kecil saya.",
  ui_story_5002_50020202_17_dialog_content = "Tapi bukannya melaporkan saya, dia malah setuju untuk membantu saya mengurusnya.",
  ui_story_5002_50020202_18_dialog_content = "Siapa namamu, nak?",
  ui_story_5002_50020202_19_dialog_content = "...",
  ui_story_5002_50020202_20_dialog_content = "Saya tidak punya nama.",
  ui_story_5002_50020202_21_dialog_content = "Oh... Lalu kenapa aku tidak memberimu satu?",
  ui_story_5002_50020202_22_dialog_content = "Aku harus memanggilmu apa? Hmm... Nah, kamu memiliki mata yang sangat cantik. Mereka mengingatkan saya pada matahari pagi di rumah!",
  ui_story_5002_50020202_23_dialog_content = "Biarkan aku berpikir... Omong-omong, aku Hawa! Senang bertemu denganmu!",
  ui_story_5002_50020202_24_dialog_content = "...",
  ui_story_5002_50020202_25_dialog_content = "Dia sama sekali tidak sulit bergaul. Dia hanya anak yang kesepian, sama sepertiku.",
  ui_story_5002_50020202_26_dialog_content = "Tapi tubuhku... Seiring waktu, aku semakin lemah dan harus bergantung padanya begitu banyak... Apakah dia tidak menyukaiku untuk itu?",
  ui_story_5002_50020202_27_dialog_content = "Aku memberitahunya tentang dunia luar sepanjang waktu. Tentang kakakku, dan orang tuaku, dan Red-Eye Gorge...",
  ui_story_5002_50020202_28_dialog_content = "Dan saya bercerita tentang bunga yang saya lihat di buku bergambar ketika saya masih kecil. Tentang bagaimana itu hanya mekar sekali dalam hidupnya, dan betapa indahnya itu.",
  ui_story_5002_50020202_29_dialog_content = "Akankah aku... membuatnya cukup lama untuk melihatnya mekar juga?",
  ui_story_5002_50020202_30_dialog_content = "...",
  ui_story_5002_50020202_31_dialog_content = "Nanti kau bisa mencicipinya.",
  ui_story_5002_50020202_32_dialog_content = "Bagaimana jika hari ini... adalah hari terakhirku di sini?",
  ui_story_5002_50020202_33_dialog_content = "Kemudian akan mekar hari ini.",
  ui_story_5002_50020202_34_dialog_content = "...",
  ui_story_5002_50020202_35_dialog_content = "Oke! Aku akan melihatnya mekar! Saya yakin itu!",
  ui_story_5002_50020202_36_dialog_content = "Dan…",
  ui_story_5002_50020202_37_dialog_content = "Fajar.",
  ui_story_5002_50020202_38_dialog_content = "Apa?",
  ui_story_5002_50020202_39_dialog_content = "Namaku. saya ingin dipanggil <color=#FFB400>Fajar</color>.",
  ui_story_5002_50020202_40_dialog_content = "Oke! Kalau begitu... Senang bertemu denganmu, Dawn!",
  ui_story_5002_50020202_41_dialog_content = "Saya tidak pernah menyangka...",
  ui_story_5002_50020202_42_dialog_content = "Hari dimana orang itu berjanji bahwa aku akan menjadi lebih baik, sebenarnya adalah...",
  ui_story_5002_50020202_43_dialog_content = "Hari pertamaku di neraka.",
  ui_story_5002_50020202_44_dialog_content = "Tunggu saja... Hawa...",
  ui_story_5002_50020202_45_dialog_content = "*Batuk* Jangan... Jangan tidur!!",
  ui_story_5002_50020202_46_dialog_content = "Apakah ... Apakah saya melakukan semua ini?",
  ui_story_5002_50020202_47_dialog_content = "Di mana para dokter? Di mana anak-anak lain?",
  ui_story_5002_50020202_A3_dialog_content = "Dia bukan dokter, Eve!",
  ui_story_5002_50020202_48_dialog_content = "Di belakang kami, di lautan api itu, aku ingat pernah melihat wanita itu...",
  ui_story_5002_50020202_49_dialog_content = "Saat dia melihat kami melarikan diri, dia melolong \"itu\"...",
  ui_story_5002_50020202_50_dialog_content = "<anim type=Shake>!!!</anim>",
  ui_story_5002_50020202_51_dialog_content = "Aku tidak tahu apakah dia kesakitan... atau dia tertawa.",
  ui_story_5002_50020202_52_dialog_content = "Eve... Bantu aku menemukan jalan kita... <color=#FFB400>Mataku</color>, mereka benar-benar terluka ...",
  ui_story_5002_50020202_53_dialog_content = "Fajar...",
  ui_story_5002_50020202_54_dialog_content = "Aku berjanji... Aku berjanji akan menunjukkan padamu...",
  ui_story_5002_50020202_55_dialog_content = "Hari dimana bunga itu akan mekar...",
  ui_story_5002_50020301_1_dialog_content = "<color=#e8d9bb>Tail Street, Tiga Tahun Lalu</color>",
  ui_story_5002_50020301_2_dialog_content = "Hujan berhenti ... Dan langit semakin cerah ...",
  ui_story_5002_50020301_3_dialog_content = "Di sana, si kecil ... jangan menangis ...",
  ui_story_5002_50020301_4_dialog_content = "...",
  ui_story_5002_50020301_5_dialog_content = "Di sana... Jangan... menangis...",
  ui_story_5002_50020301_6_dialog_content = "(Suara apa itu?)",
  ui_story_5002_50020301_7_dialog_content = "(Di mana aku?)",
  ui_story_5002_50020301_8_dialog_content = "Kakak…",
  ui_story_5002_50020301_9_dialog_content = "E...!",
  ui_story_5002_50020301_10_dialog_content = "(Orang di luar itu sangat familiar... Apa yang mereka bicarakan?)",
  ui_story_5002_50020301_11_dialog_content = "Pada suatu waktu, saya pikir itu semua hanya satu mimpi buruk besar, bahwa saya tidak perlu mendengar erangan itu lagi, begitu saya bangun.",
  ui_story_5002_50020301_12_dialog_content = "Tapi tidak ada yang bangun dari mimpi buruk ini.",
  ui_story_5002_50020301_13_dialog_content = "Saya mencoba untuk tetap terjaga selama mungkin, tetapi rasa sakitnya tetap tidak hilang.",
  ui_story_5002_50020301_14_dialog_content = "Dan hal-hal itu...",
  ui_story_5002_50020301_15_dialog_content = "Ketika malam tiba, mereka mulai bergerak di suatu tempat tidak jauh.",
  ui_story_5002_50020301_16_dialog_content = "Melalui kaca ruang isolasi, saya bisa melihat bayangan mereka di bawah sinar bulan... Saya bisa mendengar mereka berbicara dalam bahasa yang tidak saya mengerti.",
  ui_story_5002_50020301_17_dialog_content = "...",
  ui_story_5002_50020301_18_dialog_content = "Tapi tak lama kemudian... Aku mulai mengerti kata-kata mereka.",
  ui_story_5002_50020301_19_dialog_content = "Apa aku benar-benar berubah menjadi monster?",
  ui_story_5002_50020301_20_dialog_content = "Apakah saya akan menyakiti semua orang lagi?",
  ui_story_5002_50020301_21_dialog_content = "Tidak... Aku tidak bisa... Aku tidak akan membiarkan orang lain mati karena aku.",
  ui_story_5002_50020301_22_dialog_content = "Aku harus pergi dari sini.",
  ui_story_5002_50020301_23_dialog_content = "Argh…",
  ui_story_5002_50020301_24_dialog_content = "Tolong bunuh aku...",
  ui_story_5002_50020301_25_dialog_content = "Bunuh aku... dan akhiri semua ini.",
  ui_story_5002_50020301_26_dialog_content = "Saudara akan hancur, saya yakin ... Tapi ...",
  ui_story_5002_50020301_27_dialog_content = "Aku mohon padamu... Bantu aku mengakhiri semuanya.",
  ui_story_5002_50020301_28_dialog_content = "Aku... aku siap mati.",
  ui_story_5002_50020301_29_dialog_content = "Urraagh…",
  ui_story_5002_50020301_30_dialog_content = "Tapi ketika saya membuka mata, bayangan mereka hilang. Yang tersisa hanyalah sisa-sisa ruang isolasi yang hancur, dan pintu yang terbuka.",
  ui_story_5002_50020301_31_dialog_content = "Apakah mereka menyelamatkan saya?",
  ui_story_5002_50020301_32_dialog_content = "Apakah mereka melihat saya sebagai salah satu dari mereka, sekarang?",
  ui_story_5002_50020301_33_dialog_content = "Jika aku benar-benar menjadi monster suatu hari nanti...",
  ui_story_5002_50020301_34_dialog_content = "Aku tidak ingin kakak melihatku seperti itu.",
  ui_story_5002_50020301_35_dialog_content = "Aku harus pergi, sebelum Kunci Pas Rediesel menyadari aku pergi.",
  ui_story_5002_50020301_36_dialog_content = "Maaf, saudara.",
  ui_story_5002_50020301_37_dialog_content = "Kamu sudah menyerah terlalu banyak demi aku... Aku harus menemukan jalanku sendiri, sekarang.",
  ui_story_5002_50020301_38_dialog_content = "Aku tidak ingin menjadi beban bagimu lagi, saudaraku...",
  ui_story_5002_50020301_39_dialog_content = "<anim type=Shake>Aku tidak bisa membiarkan diriku menjadi beban lagi... Jika kau bisa mendengarku, aku di sini. Temui aku...</anim>",
  ui_story_5002_50020301_40_dialog_content = "<anim type=Shake>Mari kita akhiri semuanya...</anim>",
  ui_story_5002_50020302_1_dialog_content = "<anim type=Shake>Mengapa? Mengapa Anda menghentikan saya ketika saya begitu dekat ...</anim>",
  ui_story_5002_50020302_2_dialog_content = "<anim type=Shake>Saat aku hampir mengakhiri semuanya!! Mengapa?!</anim>",
  ui_story_5002_50020302_3_dialog_content = "<anim type=Shake>Harapan ... apakah benar-benar ada gunanya?</anim>",
  ui_story_5002_50020302_4_dialog_content = "Kicauan! Kicauan!",
  ui_story_5002_50020302_5_dialog_content = "<size=45><anim type=Shake>Ayo berpesta!!!</anim></size>",
  ui_story_5002_50020302_6_dialog_content = "Baiklah, lepaskan. Efek suara ini jelas bukan karya Tiny One.",
  ui_story_5002_50020302_7_dialog_content = "Mereka harus benar-benar memasukkan musik yang lebih bagus ke dalam hal ini. Ini mainan untuk Hawa, untuk menangis dengan keras!",
  ui_story_5002_50020302_8_dialog_content = "...",
  ui_story_5002_50020302_9_dialog_content = "Apakah masih sakit, Sinsa?",
  ui_story_5002_50020302_10_dialog_content = "Tidak apa-apa, selama Eve baik-baik saja. Heh, kekuatan semakin kuat dan kuat, ya?",
  ui_story_5002_50020302_11_dialog_content = "Bagaimana dengan dokter itu?",
  ui_story_5002_50020302_12_dialog_content = "Lari sebelum kami menyadarinya. Lupakan saja, kita seharusnya tahu bahwa peretasan itu tidak dapat membantu Hawa sejak awal.",
  ui_story_5002_50020302_13_dialog_content = "Aku akan memikirkan sesuatu besok. Mungkin aku akan mencari petunjuk di reruntuhan tempat kami menemukan Hawa saat itu.",
  ui_story_5002_50020302_14_dialog_content = "Dia telah menggambar lebih dan lebih Eclipsites akhir-akhir ini... Beritahu Tiny One dan Odi untuk meng-upgrade jammer sinyal.",
  ui_story_5002_50020302_15_dialog_content = "Tidak ada yang tahu...",
  ui_story_5002_50020302_16_dialog_content = "Mungkin mereka yang berbagi pengalaman serupa dengannya akan menemukan peran mereka dalam kisah misterius ini suatu hari nanti...",
  ui_story_5002_50020302_17_dialog_content = "Malam! Hawa, Hawa, Hawa!!!",
  ui_story_5002_50020302_18_dialog_content = "Sedih! Tidak bisakah kamu melihat dia masih tidur?!",
  ui_story_5002_50020302_19_dialog_content = "Nuh-uh, lihat! Dia sudah bangun!",
  ui_story_5002_50020302_20_dialog_content = "Apakah Anda tidur nyenyak tadi malam, Hawa?",
  ui_story_5002_50020302_21_dialog_content = "Kami kembali dari perburuan kami!",
  ui_story_5002_50020302_22_dialog_content = "Saya mencoba bom baru, dan itu LUAR BIASA! Saya bahkan mungkin memodifikasinya dengan kembang api!!",
  ui_story_5002_50020302_23_dialog_content = "Di sana dia pergi dengan bomnya lagi...",
  ui_story_5002_50020302_24_dialog_content = "Di mana Burung Jarum Jam, Regina?",
  ui_story_5002_50020302_25_dialog_content = "Ini.",
  ui_story_5002_50020302_26_dialog_content = "Apakah kamu menyukai mainan baru ini, Eve? Saya membuat yang merah untuk Sinsa, dan yang putih hanya untuk Anda.",
  ui_story_5002_50020302_27_dialog_content = "Ha ha ha ha! Mengapa Anda membuat Sinsa begitu jelek? Ini lucu!",
  ui_story_5002_50020302_28_dialog_content = "Beraninya kamu! Kembali kesini!!",
  ui_story_5002_50020302_29_dialog_content = "Pffffft! Tidak bisa menangkapku, pendek!",
  ui_story_5002_50020302_30_dialog_content = "...",
  ui_story_5002_50020302_31_dialog_content = "Setiap malam, hal yang paling saya nantikan adalah melihat matahari terbit.",
  ui_story_5002_50020302_32_dialog_content = "Saat fajar, semua orang akan datang dan melihat saya sebelum mereka pergi.",
  ui_story_5002_50020302_33_dialog_content = "Dan saat matahari terbenam, mereka akan memberi tahu saya semua hal yang mereka lakukan hari itu. Terkadang, mereka bahkan membawakanku hadiah...",
  ui_story_5002_50020302_34_dialog_content = "Itu adalah saat-saat paling bahagia dalam hidup saya saat itu ...",
  ui_story_5002_50020302_35_dialog_content = "Aku selalu berharap malam akan datang lebih lambat, dan pagi akan datang lebih awal...",
  ui_story_5002_50020302_36_dialog_content = "Perbaikan di ruang isolasi sudah selesai, tapi sejujurnya... Aku tidak tahu apakah akan ada perbedaan saat hal itu terjadi lagi.",
  ui_story_5002_50020302_37_dialog_content = "Itu benar. Terima kasih kembali, Odi.",
  ui_story_5002_50020302_38_dialog_content = "... Ini sama sekali tidak adil baginya. Dia hanya seorang anak kecil.",
  ui_story_5002_50020302_39_dialog_content = "Aku tahu.",
  ui_story_5002_50020302_A1_dialog_content = "Tetapi jika dia secara tidak sengaja menyakiti seseorang lagi, dia tidak akan pernah memaafkan dirinya sendiri.",
  ui_story_5002_50020302_A2_dialog_content = "Sama seperti di Red-Eye Gorge... Meskipun itu semua kesalahan Eclipsites, dia tidak pernah berhenti merasa bertanggung jawab untuk itu.",
  ui_story_5002_50020302_40_dialog_content = "Kalau saja kita tahu lebih banyak tentang apa yang terjadi saat itu ...",
  ui_story_5002_50020302_41_dialog_content = "Tapi Undercity itu bahkan tidak berada di bawah otoritas Illumina! Sial... Tidak ada yang bisa menduga semuanya akan menjadi seperti ini.",
  ui_story_5002_50020302_42_dialog_content = "Hawa bukan satu-satunya yang selamat yang lolos dari neraka itu... Tapi siapa yang menyelamatkan mereka?",
  ui_story_5002_50020302_43_dialog_content = "Saya tidak berpikir itu penting; kami cukup beruntung telah membawa Hawa kembali ke rumah, aman dan sehat. Selain itu, Anda tidak punya waktu luang untuk mengkhawatirkan hal-hal seperti itu.",
  ui_story_5002_50020302_44_dialog_content = "Kamu benar. Merawat Hawa adalah prioritas utama kami saat ini.",
  ui_story_5002_50020302_46_dialog_content = "Eve…",
  ui_story_5002_50020302_47_dialog_content = "Aku akan melakukan apapun untuk menemukan cara menyembuhkanmu. Aku akan menggali setiap gundukan di gurun ini untuk menemukannya, jika perlu.",
  ui_story_5002_50020302_48_dialog_content = "Bahkan jika saya gagal seratus kali, saya akan mencoba seribu kali lagi!",
  ui_story_5002_50020401_1_dialog_content = "Kampung halaman saya adalah Red-Eye Gorge.",
  ui_story_5002_50020401_2_dialog_content = "Ketika saya masih kecil, sesuatu yang mengerikan terjadi di sana. Aku bahkan tidak tahu seperti apa sekarang ini.",
  ui_story_5002_50020401_3_dialog_content = "Jika saya mendapat kesempatan, saya ingin kembali dan menanam bunga di seluruh Ngarai Mata Merah.",
  ui_story_5002_50020401_4_dialog_content = "Ayah dan ibu pasti suka, kan?",
  ui_story_5002_50020401_5_dialog_content = "Tapi Fajar...",
  ui_story_5002_50020401_6_dialog_content = "Jika saya tidak ... mampu melakukannya ...",
  ui_story_5002_50020401_7_dialog_content = "Maukah kamu membantuku mewujudkan keinginanku, Dawn?",
  ui_story_5002_50020401_8_dialog_content = "Eve...?",
  ui_story_5002_50020401_9_dialog_content = "Aku di sini.",
  ui_story_5002_50020401_10_dialog_content = "Hawa, ini aku! Itu PlayerName! Apakah kamu ingat saya?",
  ui_story_5002_50020401_11_dialog_content = "Tail Street, Eclipsites, Brother... Dan seseorang yang mengingat masa lalu bersamaku. Saya ingat Anda, PlayerName.",
  ui_story_5002_50020401_12_dialog_content = "Saya sangat senang! Kami masih jauh di dalam pikiranmu, Eve... Tapi semuanya tenang sekarang! Bagaimana perasaanmu?",
  ui_story_5002_50020401_13_dialog_content = "Saya baik-baik saja. Aku melihat semuanya barusan.",
  ui_story_5002_50020401_14_dialog_content = "Atau lebih tepatnya, aku merasakannya... di bagian terdalam pikiranku.",
  ui_story_5002_50020401_15_dialog_content = "Tidak ada yang pernah sampai ke tempat itu, PlayerName. Bukan saudaraku, atau bahkan Dawn.",
  ui_story_5002_50020401_16_dialog_content = "Bagaimana Anda berhasil melakukannya? Mimpi buruk itu, mereka hilang sekarang, seolah-olah mereka ditarik keluar dari pikiranku dari akarnya.",
  ui_story_5002_50020401_17_dialog_content = "Ini... sulit untuk dijelaskan. Sebut saja itu \"hadiah\" saya.",
  ui_story_5002_50020401_18_dialog_content = "Hadiahmu\"?",
  ui_story_5002_50020401_19_dialog_content = "Betul sekali. Itu adalah kekuatan yang kubawa sejak lahir... Itu juga tanggung jawabku.",
  ui_story_5002_50020401_20_dialog_content = "Seperti kamu, Hawa. Anda dilahirkan dengan kekuatan khusus juga, bukan?",
  ui_story_5002_50020401_21_dialog_content = "Ya... Tapi sampai hari ini, aku melihatnya sebagai kutukan.",
  ui_story_5002_50020401_22_dialog_content = "Kamu tidak pernah melakukan kesalahan, Eve. Anda dimanfaatkan, itu saja.",
  ui_story_5002_50020401_A1_dialog_content = "Aku masih ingat hari dimana semuanya dimulai. Aku dengan egois meninggalkan desa, dan kemudian...",
  ui_story_5002_50020401_A2_dialog_content = "Saya menemukan mereka.",
  ui_story_5002_50020401_A3_dialog_content = "Aku tidak ingat apa yang mereka lakukan padaku, tapi semacam kekuatan pasti terbangun di dalam diriku... kekuatan yang menakutkan.",
  ui_story_5002_50020401_A4_dialog_content = "Tetapi bagian terburuknya adalah bahkan dengan kekuatan baru ini, saya masih tidak bisa menyelamatkan keluarga saya atau penduduk desa lainnya.",
  ui_story_5002_50020401_A5_dialog_content = "Eclipsites masih menghancurkan Red-Eye Gorge... Dan aku dan saudaraku adalah satu-satunya yang selamat.",
  ui_story_5002_50020401_A6_dialog_content = "Siapa yang akan membantu saya? Siapa yang mau menerima monster sepertiku?",
  ui_story_5002_50020401_A7_dialog_content = "Itu sebabnya, ketika wanita itu muncul suatu hari, saya pikir saya akhirnya akan diselamatkan.",
  ui_story_5002_50020401_A8_dialog_content = "Saya tidak pernah berpikir bahwa dia hanya ingin mengeksploitasi saya, dan orang lain seperti saya, untuk melakukan \"penelitian\"-nya.",
  ui_story_5002_50020401_A9_dialog_content = "Saya akhirnya merasa cukup. Saat itu, kekuatanku tidak terkendali dan itu menghancurkan seluruh Kota Bawah.",
  ui_story_5002_50020401_A10_dialog_content = "Dawn membantuku melarikan diri dari tempat itu. Itu benar... Seseorang harus melindungiku lagi.",
  ui_story_5002_50020401_A11_dialog_content = "Saya tidak ingat kapan atau bagaimana saudara saya menemukan saya, tetapi kami akhirnya bersatu kembali.",
  ui_story_5002_50020401_A12_dialog_content = "Dia... Dia tidak menyalahkanku atau memarahiku sekali pun. Sebaliknya, dia meminta maaf kepada saya ...",
  ui_story_5002_50020401_A13_dialog_content = "Aku hanya ingin melindungi semua orang... jika hanya sekali.",
  ui_story_5002_50020401_23_dialog_content = "...",
  ui_story_5002_50020401_24_dialog_content = "Eve?",
  ui_story_5002_50020401_26_dialog_content = "Kamu menangis...?",
  ui_story_5002_50020401_27_dialog_content = "Tidak, bukan aku. Hidungku hanya... sedikit tersumbat, itu saja.",
  ui_story_5002_50020401_28_dialog_content = "Anda benar-benar tidak berpikir ini semua salahku? Kakak... Fajar... Semuanya... Mereka benar-benar tidak menyalahkanku untuk semuanya?",
  ui_story_5002_50020401_29_dialog_content = "Tidak ada yang pernah menyalahkanmu, Hawa. Mereka semua menunggumu.",
  ui_story_5002_50020401_30_dialog_content = "Kapan pun Anda siap, kita bisa pergi ke sana dan melihat semuanya.",
  ui_story_5002_50020401_32_dialog_content = "Brrr! Kenapa tiba-tiba jadi dingin?",
  ui_story_5002_50020401_33_dialog_content = "Di mana \"di luar sana,\" PlayerName?",
  ui_story_5002_50020401_34_dialog_content = "Ngarai Mata Merah, kampung halaman Anda. Tidakkah kamu ingat? Anda dan Dawn datang ke sini bersama-sama.",
  ui_story_5002_50020401_35_dialog_content = "Ngarai Mata Merah... Tapi badai...",
  ui_story_5002_50020401_A14_dialog_content = "Menjauh! Jangan dekati desaku!!",
  ui_story_5002_50020401_A15_dialog_content = "Aku tidak akan membiarkanmu menyakiti siapa pun!!!",
  ui_story_5002_50020401_A16_dialog_content = "Kemana perginya Eclipsites?!",
  ui_story_5002_50020401_A17_dialog_content = "(Eclipsian) Petir?! Dari mana asalnya? Siapa yang bertanggung jawab?!",
  ui_story_5002_50020401_A18_dialog_content = "(Eclipsian) Awan itu... Apa yang telah kamu lakukan, Aurorian?!",
  ui_story_5002_50020401_A19_dialog_content = "J-Jangan mendekat!!",
  ui_story_5002_50020401_A20_dialog_content = "Malam! Mencari!!",
  ui_story_5002_50020401_A21_dialog_content = "Saudara laki-laki! Tanganmu!!",
  ui_story_5002_50020401_A22_dialog_content = "Aku baru ingat badai!",
  ui_story_5002_50020401_36_dialog_content = "Itu benar, tapi badai mulai mendekati kita. Dalam situasi ini...",
  ui_story_5002_50020401_37_dialog_content = "Hrrgh!!",
  ui_story_5002_50020401_38_dialog_content = "Ini sangat dingin... Kita kehabisan waktu...",
  ui_story_5002_50020401_40_dialog_content = "Sial, koneksinya melemah... Sepertinya aku akan bangun.",
  ui_story_5002_50020401_41_dialog_content = "PlayerName... Jika badai muncul karena aku, maka aku ingin mencoba sesuatu...",
  ui_story_5002_50020401_42_dialog_content = "Hah?",
  ui_story_5002_50020401_43_dialog_content = "Badai... Aku akan...",
  ui_story_5002_50020401_44_dialog_content = "Malam! Apakah kamu masih di sana, Hawa?",
  ui_story_5002_50020401_45_dialog_content = "Kamu pergi dulu... Aku akan baik-baik saja...",
  ui_story_5002_50020401_46_dialog_content = "Malam? Aku tidak bisa mendengarmu!",
  ui_story_5002_50020401_47_dialog_content = "Terima kasih, ! Dan tolong... beri semua orang terima kasihku juga...",
  ui_story_5002_50020401_A23_dialog_content = "Terima kasih untuk akhirnya... memberiku kesempatan... untuk melindungi semua orang.",
  ui_story_5002_50020401_48_dialog_content = "Eve?",
  ui_story_5002_50020401_49_dialog_content = "Malam!!!",
  ui_story_5002_50020401_50_dialog_content = "PlayerName! Kau sudah bangun!",
  ui_story_5002_50020401_51_dialog_content = "Apa ini di wajahku? Mengapa hujan berwarna merah...?",
  ui_story_5002_50020401_52_dialog_content = "Anda berdarah dari hidung Anda. Tubuhmu tiba-tiba tersentak barusan, begitu pula Hawa. Apa yang terjadi? Apakah Anda menemukannya?",
  ui_story_5002_50020401_53_dialog_content = "Aku tidak hanya menemukannya... Aku <color=#FFB400>melakukannya</color>...",
  ui_story_5002_50020401_54_dialog_content = "Saya melakukan apa yang perlu dilakukan. Pikiran Eve akhirnya stabil...",
  ui_story_5002_50020401_55_dialog_content = "Lalu kenapa dia belum bangun, sialan?!",
  ui_story_5002_50020401_56_dialog_content = "Hentikan, Sinsa! PlayerName benar-benar lemah sekarang dan butuh istirahat! Anda harus mempercayai Caelestite kami!",
  ui_story_5002_50020401_57_dialog_content = "Bos! Badai mendekati kita lagi!!",
  ui_story_5002_50020401_58_dialog_content = "Sudah terlambat. Tekanan angin ini... Tidak ada jalan keluar.",
  ui_story_5002_50020401_59_dialog_content = "Seperti neraka, tidak ada! Aku akan mengeluarkan Hawa dari sini jika aku harus membuat lubang di badai sialan ini dengan tangan kosong!!",
  ui_story_5002_50020401_60_dialog_content = "Bagaimana dengan Soroz? Colossus mungkin bisa membawa kita...",
  ui_story_5002_50020401_61_dialog_content = "Soroz dekat, PlayerName.",
  ui_story_5002_50020401_62_dialog_content = "Memang. Mata badai mulai menyusut dengan cepat, jadi saya yakin bergabung dengan Anda akan menjadi pilihan terbaik kami.",
  ui_story_5002_50020401_63_dialog_content = "Apakah Anda selesai memperbaiki diri sendiri, Soroz?",
  ui_story_5002_50020401_64_dialog_content = "Perbaikan kabel telah selesai, bersama dengan beberapa perbaikan kecil lainnya... Tapi badai ini jauh lebih kuat dari sebelumnya.",
  ui_story_5002_50020401_65_dialog_content = "Saya minta maaf, tetapi saya bahkan tidak bisa mendekatinya tanpa terkoyak, apalagi melewatinya.",
  ui_story_5002_50020401_66_dialog_content = "Hmm…",
  ui_story_5002_50020401_67_dialog_content = "Semuanya, ke dalam Colossus! Ini akan memberi kita waktu untuk memikirkan sesuatu! Cepat, bawa Hawa dan pergi!",
  ui_story_5002_50020401_68_dialog_content = "Argh!!",
  ui_story_5002_50020401_69_dialog_content = "Sinsa! Apakah kamu terluka?",
  ui_story_5002_50020401_70_dialog_content = "Ini Eve, dia melakukannya lagi... Tunggu, <color=#FFB400>energi ini</color>...?!",
  ui_story_5002_50020401_71_dialog_content = "Apakah dia melepaskan kekuatannya lagi?",
  ui_story_5002_50020401_72_dialog_content = "Tidak, itu kebalikannya... Dia sebenarnya...",
  ui_story_5002_50020401_73_dialog_content = "<color=#FFB400>Menyerap energi</color>!",
  ui_story_5002_50020401_74_dialog_content = "?!",
  ui_story_5002_50020401_75_dialog_content = "Petir! Kembali!!",
  ui_story_5002_50020401_77_dialog_content = "Ahhhh!!",
  ui_story_5002_50020401_78_dialog_content = "Lepaskan, Sina!! Kesini!!",
  ui_story_5002_50020401_79_dialog_content = "E-Eve... Dia masih...",
  ui_story_5002_50020401_80_dialog_content = "Angin berubah arah... Sinsa, badai mulai berkumpul di satu tempat!",
  ui_story_5002_50020401_81_dialog_content = "Listrik di udara, seperti milik Hawa... Apakah dia secara tidak sadar menyerap badai?!",
  ui_story_5002_50020401_82_dialog_content = "Apakah itu mungkin? Badai cukup besar untuk mengelilingi semua Red-Eye Gorge!",
  ui_story_5002_50020401_83_dialog_content = "Petir di tengah badai... Sepertinya itu berkonsentrasi pada tubuh Hawa!",
  ui_story_5002_50020401_84_dialog_content = "Apa yang dia lakukan? Apakah dia benar-benar menyerap seluruh kekuatan badai?!",
  ui_story_5002_50020401_85_dialog_content = "Memang, badai tampaknya sedang surut. Perempuan ini...",
  ui_story_5002_50020401_86_dialog_content = "Bagaimana kabarnya, Sinsa?!",
  ui_story_5002_50020401_87_dialog_content = "Dia baik-baik saja! Hawa... Uwaagh...!",
  ui_story_5002_50020401_88_dialog_content = "Kakak ada di sini, Eve... Aku tidak akan pernah... Melepaskanmu...!!",
  ui_story_5002_50020401_89_dialog_content = "PlayerName! Langit!",
  ui_story_5002_50020401_90_dialog_content = "Lihat ke langit!",
  ui_story_5002_50020401_91_dialog_content = "Dimana saya?",
  ui_story_5002_50020401_92_dialog_content = "Eve?",
  ui_story_5002_50020401_93_dialog_content = "Ibu? Ayah?",
  ui_story_5002_50020401_94_dialog_content = "Anda masih hidup ... Syukurlah, Anda berdua masih hidup ...",
  ui_story_5002_50020401_95_dialog_content = "...",
  ui_story_5002_50020401_96_dialog_content = "Hawa... Kau tersenyum?",
  ui_story_5002_50020401_97_dialog_content = "...",
  ui_story_5002_50020401_98_dialog_content = "Tunggu, kamu mau kemana? Tunggu aku!",
  ui_story_5002_50020401_99_dialog_content = "Pegang tanganku! Jangan tinggalkan aku...",
  ui_story_5002_50020401_100_dialog_content = "Hmm…",
  ui_story_5002_50020401_101_dialog_content = "Kembalilah... Jangan pergi...",
  ui_story_5002_50020401_102_dialog_content = "Jangan... Jangan tinggalkan aku sendiri lagi...",
  ui_story_5002_50020401_103_dialog_content = "...",
  ui_story_5002_50020401_104_dialog_content = "Hmm…",
  ui_story_5002_50020401_105_dialog_content = "Tidak bisa... bernapas...!",
  ui_story_5002_50020401_106_dialog_content = "…?",
  ui_story_5002_50020401_107_dialog_content = "Anda menghancurkan saya, saudara ...",
  ui_story_5002_50020401_108_dialog_content = "Hawa, kamu...",
  ui_story_5002_50020401_109_dialog_content = "Mmhmm... Aku kembali, saudaraku.",
  ui_story_5002_50020401_110_dialog_content = "Ngarai Mata Merah... Cuacanya bagus, ya?",
  ui_story_5002_50020401_111_dialog_content = "Ya... hujan berhenti.",
  ui_story_5002_50020401_112_dialog_content = "Saudaraku, wajahmu ...",
  ui_story_5002_50020401_113_dialog_content = "... Terlihat lebih tua.",
  ui_story_5002_50020401_114_dialog_content = "Itu benar, Hawa. Semua ini membuatku tua seperti orang gila.",
  ui_story_5002_50020401_115_dialog_content = "Terima kasih.",
  ui_story_5002_50020401_116_dialog_content = "Eve…",
  ui_story_5002_50020401_117_dialog_content = "Terima kasih saudara.",
  ui_story_5002_50020401_118_dialog_content = "Tidak...",
  ui_story_5002_50020401_119_dialog_content = "Jangan, Hawa. Seharusnya aku berterima kasih padamu.",
  ui_story_5002_50020401_120_dialog_content = "Di sana, jangan menangis saudaraku. Air matamu jatuh di wajahku...",
  ui_story_5002_50020401_121_dialog_content = "Di sana, anak kecil... Jangan menangis... Hujan sudah reda, dan matahari bersinar...",
  ui_story_5002_50020401_122_dialog_content = "aku... aku tahu. Hujan akhirnya reda... dan matahari bersinar lagi.",
  ui_story_5002_50020401_123_dialog_content = "Jadi tidak ada lagi tangisan, si kecil... Tidak ada lagi tangisan."
}
